import React, { useState, useRef, useEffect, useCallback, memo } from 'react';
import { Flow } from 'flow-sdk';
import { Icon } from './components/Icon';
import { Sidebar } from './components/Sidebar';
import { Stage } from './components/Stage';
import { Timeline } from './components/Timeline';
import { TextConfig, SketchConfig, SketchPath, MediaAsset, FONTS, GOOGLE_FONTS_URL, SKETCH_ACCENT_COLOR, GlobalBrush } from './types';
import { renderVideo } from './services/renderer';

import { timeController } from './services/TimeController';

const MemoizedSidebar = memo(Sidebar);

// ── Runtime injection of fonts + global CSS (index.html is ignored in Flow sandbox) ──
const INJECTED_STYLE_ID = 'videosketch-global-styles';
const INJECTED_FONT_ID = 'videosketch-material-symbols';
const INJECTED_BODY_FONT_ID = 'videosketch-google-sans';

function useGlobalStyles() {
    useEffect(() => {
        const preconnect1 = document.createElement('link');
        preconnect1.rel = 'preconnect';
        preconnect1.href = 'https://fonts.googleapis.com';
        document.head.appendChild(preconnect1);

        const preconnect2 = document.createElement('link');
        preconnect2.rel = 'preconnect';
        preconnect2.href = 'https://fonts.gstatic.com';
        preconnect2.crossOrigin = 'anonymous';
        document.head.appendChild(preconnect2);

        if (!document.getElementById(INJECTED_FONT_ID)) {
            const fontLink = document.createElement('link');
            fontLink.id = INJECTED_FONT_ID;
            fontLink.rel = 'stylesheet';
            fontLink.href = 'https://fonts.googleapis.com/css2?family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200&display=swap';
            document.head.appendChild(fontLink);
        }

        if (!document.getElementById(INJECTED_BODY_FONT_ID)) {
            const bodyFont = document.createElement('link');
            bodyFont.id = INJECTED_BODY_FONT_ID;
            bodyFont.rel = 'stylesheet';
            bodyFont.href = 'https://fonts.googleapis.com/css2?family=Google+Sans:wght@400;500;600;700&family=Google+Sans+Flex:wght@400;500;600;700&family=Google+Sans+Text:wght@400;500;600;700&display=swap';
            document.head.appendChild(bodyFont);
        }

        // Load text layer fonts (Instrument Sans etc.)
        const textFontLink = document.createElement('link');
        textFontLink.rel = 'stylesheet';
        textFontLink.crossOrigin = 'anonymous';
        textFontLink.href = GOOGLE_FONTS_URL;
        document.head.appendChild(textFontLink);

        if (!document.getElementById(INJECTED_STYLE_ID)) {
            const style = document.createElement('style');
            style.id = INJECTED_STYLE_ID;
            style.textContent = `\n                * { box-sizing: border-box; }\n                .material-symbols-rounded { font-variation-settings: 'FILL' 0, 'wght' 300, 'GRAD' 0, 'opsz' 20; }\n                .no-scrollbar::-webkit-scrollbar { display: none; }\n                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }\n\n                input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; }\n                input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }\n                input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 10px; height: 10px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -3.5px; cursor: pointer; }\n                input[type=range]::-moz-range-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }\n                input[type=range]::-moz-range-thumb { width: 10px; height: 10px; border: none; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); cursor: pointer; }\n\n                .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #2a2a2a transparent; }\n                .dark-scrollbar::-webkit-scrollbar { width: 3px; }\n                .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }\n                .dark-scrollbar::-webkit-scrollbar-thumb { background: #2a2a2a; border-radius: 9999px; }\n                .dark-scrollbar::-webkit-scrollbar-thumb:hover { background: #444; }\n\n                @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }\n                .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }\n\n                @keyframes layer-enter { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }\n                .animate-layer { animation: layer-enter 0.2s ease-out forwards; }\n\n                @keyframes flash-glow { 0% { filter: drop-shadow(0 0 0px transparent); } 20% { filter: drop-shadow(0 0 14px rgba(255,255,255,0.5)); } 100% { filter: drop-shadow(0 0 0px transparent); } }\n                .flash-glow { animation: flash-glow 0.4s cubic-bezier(0.22,0.68,0,1) forwards; }\n\n                .braille-loader { display: flex; gap: 6px; align-items: center; }\n                .braille-loader span { width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,0.5); animation: braille-bounce 1.2s cubic-bezier(0.4,0,0.2,1) infinite; }\n                .braille-loader span:nth-child(1) { animation-delay: 0s; }\n                .braille-loader span:nth-child(2) { animation-delay: 0.15s; }\n                .braille-loader span:nth-child(3) { animation-delay: 0.3s; }\n                .braille-loader span:nth-child(4) { animation-delay: 0.45s; }\n                @keyframes braille-bounce { 0%,60%,100% { opacity: 0.2; transform: scale(0.8); } 30% { opacity: 1; transform: scale(1.2); } }\n\n                html, body, #root {\n                    margin: 0; padding: 0; width: 100%; height: 100%;\n                    background: #0e0e0e;\n                    font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif;\n                    -webkit-font-smoothing: antialiased;\n                    -moz-osx-font-smoothing: grayscale;\n                }\n            `;
            document.head.appendChild(style);
        }

        return () => {
            preconnect1.remove();
            preconnect2.remove();
            textFontLink.remove();
        };
    }, []);
}

export default function App() {
    useGlobalStyles();

    const [bgMedia, setBgMedia] = useState<MediaAsset | null>(null);
    const [duration, setDuration] = useState(8);
    const [textConfigs, setTextConfigs] = useState<TextConfig[]>([]);
    const [selectedTextId, setSelectedTextId] = useState<string | null>('sketch-1');
    const [sketchConfigs, setSketchConfigs] = useState<SketchConfig[]>([
        {
            type: 'sketch',
            id: 'sketch-1',
            name: 'Sketch 1',
            paths: [],
            strokeWidth: 6,
            strokeColor: '#FF5E5E',
            strokeOpacity: 1,
            effect: 'none',
            accentColor: SKETCH_ACCENT_COLOR,
            delay: 0,
            duration: 8000,
            inDuration: 0,
            outDuration: 0,
            brushType: 'brush',
        }
    ]);

    // Global brush settings — shared across all sketch layers
    const [globalBrush, setGlobalBrush] = useState<GlobalBrush>({
        strokeColor: '#FF5E5E',
        strokeWidth: 6,
        strokeOpacity: 1,
        brushType: 'brush',
    });

    const [isPlaying, setIsPlaying] = useState(false);
    const [isRendering, setIsRendering] = useState(false);
    const [renderProgress, setRenderProgress] = useState(0);
    const [exportedMedia, setExportedMedia] = useState<{ dataUrl: string, mimeType: string } | null>(null);
    const prevExportUrl = useRef<string | null>(null);
    const abortControllerRef = useRef<AbortController | null>(null);
    const [key, setKey] = useState(0);
    const [flashLayerId, setFlashLayerId] = useState<string | null>(null);
    const flashTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

    // Per-sketch undo/redo stacks (keyed by sketch id)
    const sketchUndoStacks = useRef<Record<string, SketchPath[][]>>({});
    const sketchRedoStacks = useRef<Record<string, SketchPath[][]>>({});

    const selectedConfig = textConfigs.find(c => c.id === selectedTextId) || null;
    const selectedSketch = sketchConfigs.find(s => s.id === selectedTextId) || null;

    const handleDeleteLayer = useCallback((id: string) => {
        const totalLayers = textConfigs.length + sketchConfigs.length;
        if (totalLayers <= 1) return;

        // Check if it's a text layer or sketch layer
        const isText = textConfigs.some(c => c.id === id);
        const isSketch = sketchConfigs.some(s => s.id === id);

        if (selectedTextId === id) {
            // Pick the next layer from all layers
            const allIds = [...textConfigs.map(c => c.id), ...sketchConfigs.map(s => s.id)];
            const idx = allIds.indexOf(id);
            const nextId = allIds[idx + 1] ?? allIds[idx - 1] ?? null;
            setSelectedTextId(nextId);
        }

        if (isText) {
            setTextConfigs(prev => prev.filter(c => c.id !== id));
        } else if (isSketch) {
            setSketchConfigs(prev => prev.filter(s => s.id !== id));
        }
    }, [textConfigs, sketchConfigs, selectedTextId]);

    const handleSketchUndo = useCallback(() => {
        const id = selectedTextId;
        if (!id) return;
        const undoStack = sketchUndoStacks.current[id];
        if (!undoStack || undoStack.length === 0) return;

        const previousPaths = undoStack.pop()!;
        setSketchConfigs(prev => {
            const current = prev.find(s => s.id === id);
            if (current) {
                if (!sketchRedoStacks.current[id]) sketchRedoStacks.current[id] = [];
                sketchRedoStacks.current[id].push([...current.paths]);
            }
            return prev.map(s => s.id === id ? { ...s, paths: previousPaths } : s);
        });
    }, [selectedTextId]);

    const handleSketchRedo = useCallback(() => {
        const id = selectedTextId;
        if (!id) return;
        const redoStack = sketchRedoStacks.current[id];
        if (!redoStack || redoStack.length === 0) return;

        const nextPaths = redoStack.pop()!;
        setSketchConfigs(prev => {
            const current = prev.find(s => s.id === id);
            if (current) {
                if (!sketchUndoStacks.current[id]) sketchUndoStacks.current[id] = [];
                sketchUndoStacks.current[id].push([...current.paths]);
            }
            return prev.map(s => s.id === id ? { ...s, paths: nextPaths } : s);
        });
    }, [selectedTextId]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            const activeElement = document.activeElement;
            const isInput = activeElement &&
                (activeElement.tagName === 'INPUT' ||
                    activeElement.tagName === 'TEXTAREA' ||
                    (activeElement instanceof HTMLElement && activeElement.isContentEditable));

            if (isInput) return;

            if ((e.metaKey || e.ctrlKey) && e.key === 'z' && !e.shiftKey) {
                e.preventDefault();
                handleSketchUndo();
                return;
            }
            if ((e.metaKey || e.ctrlKey) && (e.key === 'z' && e.shiftKey || e.key === 'y')) {
                e.preventDefault();
                handleSketchRedo();
                return;
            }

            if (e.key === ' ' || e.code === 'Space') {
                e.preventDefault();
                setIsPlaying(prev => !prev);
            } else if (e.key === 'Backspace' || e.key === 'Delete') {
                if (selectedTextId) {
                    e.preventDefault();
                    handleDeleteLayer(selectedTextId);
                }
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => {
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, [selectedTextId, handleDeleteLayer, handleSketchUndo, handleSketchRedo]);

    const handleSelectMedia = async () => {
        try {
            const media = await Flow.media.select({ filter: 'all' });
            if (media) {
                const bytes = Uint8Array.from(atob(media.base64), c => c.charCodeAt(0));
                const blob = new Blob([bytes], { type: media.mimeType });
                const file = new File([blob], media.name || 'bg-media', { type: media.mimeType });
                const dataUrl = URL.createObjectURL(file);
                const type = media.type;
                setBgMedia({ type, dataUrl, mimeType: media.mimeType });
                setIsPlaying(true);
                timeController.setTime(0);
            }
        } catch (err) {
            console.error('Failed to select media', err);
        }
    };

    /** Shared helper — compute clamped delay + duration for a new layer at the playhead */
    const clampNewLayerTiming = useCallback((defaultDurMs: number) => {
        const totalMs = duration * 1000;
        let delay = Math.round(timeController.getTime() * 1000);
        if (delay + defaultDurMs > totalMs) delay = Math.max(0, totalMs - defaultDurMs);
        const dur = Math.max(500, Math.min(defaultDurMs, totalMs - delay));
        return { delay, duration: dur };
    }, [duration]);

    const handleAddLayer = useCallback(() => {
        const newId = Math.random().toString(36).substr(2, 9);
        const { delay, duration: layerDuration } = clampNewLayerTiming(2200);

        const lastLayer = textConfigs[textConfigs.length - 1];
        const newLayer: TextConfig = {
            ...(lastLayer || {
                fontFamily: "'Instrument Sans', sans-serif",
                fontSize: 84,
                fontWeight: 500,
                letterSpacing: 0,
                lineHeight: 1,
                textAlign: 'center',
                color: '#ffffff',
                backgroundColor: '#000000',
                bgOpacity: 0,
                effect: 'none',
                granularity: 'word',
                easing: 'smooth',
                speed: 1,
                stackTransition: 'blur',
                intensity: 50,
            }),
            id: newId,
            content: 'New Text',
            position: { x: 50, y: 50 },
            delay,
            duration: layerDuration,
            inDuration: 0,
            outDuration: 0,
            intensity: 50,
        };
        setTextConfigs(prev => [...prev, newLayer]);
        setSelectedTextId(newId);

        // Seek playhead to just after new layer start
        const visibleTime = (delay + 100) / 1000;
        const endTime = (delay + layerDuration) / 1000;
        timeController.setTime(Math.min(visibleTime, endTime, duration));
    }, [textConfigs, duration, clampNewLayerTiming]);

    const handleAddSketchLayer = useCallback(() => {
        const newId = 'sk_' + Math.random().toString(36).substr(2, 9);
        const { delay, duration: layerDuration } = clampNewLayerTiming(3000);

        const newSketch: SketchConfig = {
            type: 'sketch',
            id: newId,
            name: `Sketch ${sketchConfigs.length + 1}`,
            paths: [],
            strokeColor: globalBrush.strokeColor,
            strokeWidth: globalBrush.strokeWidth,
            strokeOpacity: globalBrush.strokeOpacity,
            effect: 'none',
            brushType: globalBrush.brushType,
            accentColor: SKETCH_ACCENT_COLOR,
            duration: layerDuration,
            delay,
            inDuration: 0,
            outDuration: 0,
        };

        setSketchConfigs(prev => [...prev, newSketch]);
        setSelectedTextId(newId);

        const visibleTime = (delay + Math.min(900, layerDuration / 2)) / 1000;
        timeController.setTime(Math.min(visibleTime, duration));
    }, [sketchConfigs, duration, globalBrush, clampNewLayerTiming]);

    const handleExport = async () => {
        // Save play state and pause so Stage.tsx's updateLoop doesn't override the TimeController
        const wasPlaying = isPlaying;
        if (isPlaying) setIsPlaying(false);

        setIsRendering(true);
        setRenderProgress(0);

        const controller = new AbortController();
        abortControllerRef.current = controller;

        try {
            const result = await renderVideo(bgMedia, textConfigs, (p) => setRenderProgress(p), controller.signal, sketchConfigs, duration);
            // Revoke previous export blob URL to free memory
            if (prevExportUrl.current) URL.revokeObjectURL(prevExportUrl.current);
            prevExportUrl.current = result.dataUrl;
            setExportedMedia({ dataUrl: result.dataUrl, mimeType: result.mimeType });
        } catch (err) {
            if (err instanceof Error && err.message === "Render cancelled") {
                console.log('Render cancelled by user');
            } else {
                console.error('Render failed', err);
            }
        } finally {
            setIsRendering(false);
            if (wasPlaying) setIsPlaying(true);
            abortControllerRef.current = null;
        }
    };

    const updateTextConfig = useCallback((updates: Partial<TextConfig>, id?: string) => {
        const targetId = id || selectedTextId;
        setTextConfigs(prev => prev.map(c =>
            c.id === targetId ? { ...c, ...updates } : c
        ));
    }, [selectedTextId]);

    const batchUpdateConfigs = useCallback((updates: Array<{ id: string; changes: Partial<TextConfig | SketchConfig> }>) => {
        setTextConfigs(prev => prev.map(c => {
            const update = updates.find(u => u.id === c.id);
            return update ? { ...c, ...update.changes as Partial<TextConfig> } : c;
        }));
        setSketchConfigs(prev => prev.map(s => {
            const update = updates.find(u => u.id === s.id);
            return update ? { ...s, ...update.changes as Partial<SketchConfig> } : s;
        }));
    }, []);

    const updateSketchConfig = useCallback((updates: Partial<SketchConfig>, id?: string) => {
        const targetId = id || selectedTextId;
        if (!targetId) return;

        // If paths are being updated (e.g. Clear All), push to undo stack
        if ('paths' in updates) {
            setSketchConfigs(prev => {
                const current = prev.find(s => s.id === targetId);
                if (current) {
                    if (!sketchUndoStacks.current[targetId]) sketchUndoStacks.current[targetId] = [];
                    sketchUndoStacks.current[targetId].push([...current.paths]);
                    sketchRedoStacks.current[targetId] = [];
                }
                return prev.map(s => s.id === targetId ? { ...s, ...updates } : s);
            });
        } else {
            setSketchConfigs(prev => prev.map(s =>
                s.id === targetId ? { ...s, ...updates } : s
            ));
        }
    }, [selectedTextId]);

    const handleUpdateSketchPaths = useCallback((id: string, paths: SketchPath[]) => {
        // Push current state to undo stack before updating
        setSketchConfigs(prev => {
            const current = prev.find(s => s.id === id);
            if (current) {
                if (!sketchUndoStacks.current[id]) sketchUndoStacks.current[id] = [];
                sketchUndoStacks.current[id].push([...current.paths]);
                // Clear redo on new action
                sketchRedoStacks.current[id] = [];
            }
            return prev.map(s => s.id === id ? { ...s, paths } : s);
        });
    }, []);

    const handleRestart = useCallback(() => {
        setIsPlaying(false);
        timeController.setTime(0);
        setKey(prev => prev + 1);
    }, []);

    const handleTimelineSeek = useCallback((time: number) => {
        timeController.setTime(time);
    }, []);

    const handlePause = useCallback(() => {
        setIsPlaying(false);
    }, []);

    // Enhanced layer selection: flash glow + jump scrubber to layer
    const handleSelectLayer = useCallback((id: string) => {
        setSelectedTextId(id);

        // Flash glow
        if (flashTimeout.current) clearTimeout(flashTimeout.current);
        setFlashLayerId(id);
        flashTimeout.current = setTimeout(() => setFlashLayerId(null), 400);

        // Jump scrubber to layer start
        const layer = [...textConfigs, ...sketchConfigs].find(l => l.id === id);
        if (layer) {
            const visibleTime = (layer.delay + Math.min(layer.inDuration || 0, 100) + 100) / 1000;
            const endTime = (layer.delay + layer.duration) / 1000;
            timeController.setTime(Math.min(visibleTime, endTime, duration));
        }
    }, [textConfigs, sketchConfigs, duration]);

    const handlePlayPause = useCallback(() => setIsPlaying(prev => !prev), []);

    return (
        <div className="fixed inset-0 w-screen h-screen bg-[#0a0a0a] text-[#ededed] flex overflow-hidden font-sans">
            {/* Main Workspace */}
            <div className="flex-1 flex flex-col min-w-0 h-full p-8 lg:p-12 overflow-hidden">
                {/* Stage Container with defined space */}
                <div className="flex-1 flex items-center justify-center min-h-0 relative mb-8 overflow-hidden">
                    <Stage
                        media={bgMedia}
                        configs={textConfigs}
                        sketchConfigs={sketchConfigs}
                        selectedId={isRendering ? null : selectedTextId}
                        isPlaying={isPlaying}
                        animationKey={key}
                        flashLayerId={flashLayerId}
                        onUpdatePosition={(pos) => updateTextConfig({ position: pos })}
                        onUpdateSketchPaths={handleUpdateSketchPaths}
                        onMetadataLoaded={(d) => {
                            setDuration(d);
                            // Sync sketch-1 to span the full timeline
                            setSketchConfigs(prev => prev.map(s =>
                                s.id === 'sketch-1' ? { ...s, duration: d * 1000 } : s
                            ));
                        }}
                        onSelectLayer={handleSelectLayer}
                        onPause={handlePause}
                        onAutoAddSketchLayer={handleAddSketchLayer}
                        globalBrush={globalBrush}
                        placeholderDuration={8}
                    />
                </div>

                {/* Timeline Area - Fixed height, won&apos;t overlap */}
                <div className="shrink-0 w-full max-w-5xl mx-auto px-6">
                    <Timeline
                        duration={duration}
                        configs={textConfigs}
                        sketchConfigs={sketchConfigs}
                        selectedId={selectedTextId}
                        isPlaying={isPlaying}
                        onPlayPause={handlePlayPause}
                        onRestart={handleRestart}
                        onSeek={handleTimelineSeek}
                        onUpdateConfig={updateTextConfig}
                        onUpdateSketchConfig={updateSketchConfig}
                        onBatchUpdate={batchUpdateConfigs}
                        onSelectLayer={handleSelectLayer}
                    />
                </div>
            </div>

            <MemoizedSidebar
                config={selectedConfig}
                selectedSketch={selectedSketch}
                allConfigs={textConfigs}
                allSketches={sketchConfigs}
                onUpdate={updateTextConfig}
                onUpdateSketch={updateSketchConfig}
                onSelectMedia={handleSelectMedia}
                onDeleteLayer={handleDeleteLayer}
                onSelectLayer={handleSelectLayer}
                onAddLayer={handleAddLayer}
                onAddSketchLayer={handleAddSketchLayer}
                onExport={handleExport}
                isRendering={isRendering}
                renderProgress={renderProgress}
                hasMedia={!!bgMedia}
                onSketchUndo={handleSketchUndo}
                onSketchRedo={handleSketchRedo}
                canSketchUndo={!!(selectedSketch && sketchUndoStacks.current[selectedSketch.id]?.length > 0)}
                canSketchRedo={!!(selectedSketch && sketchRedoStacks.current[selectedSketch.id]?.length > 0)}
                globalBrush={globalBrush}
                onUpdateGlobalBrush={setGlobalBrush}
            />

            {/* Export Popup */}
            {exportedMedia && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-8" onClick={() => setExportedMedia(null)}>
                    <div className="bg-[#0a0a0a] border border-[rgba(218,220,224,0.15)] rounded-xl p-5 shadow-2xl max-w-2xl w-full flex flex-col gap-5" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center justify-between">
                            <h2 className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">Render Complete</h2>
                            <button
                                onClick={() => setExportedMedia(null)}
                                className="text-[rgba(218,220,224,0.35)] hover:text-white transition-colors p-1"
                            >
                                <Icon name="close" size={16} />
                            </button>
                        </div>

                        <div className="rounded-xl overflow-hidden bg-black border border-[rgba(218,220,224,0.15)] flex items-center justify-center min-h-[300px]">
                            {exportedMedia.mimeType.startsWith('video/') ? (
                                <video
                                    src={exportedMedia.dataUrl}
                                    controls
                                    autoPlay
                                    loop
                                    className="max-h-[60vh] max-w-full object-contain"
                                />
                            ) : (
                                <img
                                    src={exportedMedia.dataUrl}
                                    alt="Exported result"
                                    className="max-h-[60vh] max-w-full object-contain"
                                />
                            )}
                        </div>

                        <div className="flex gap-[5px] pt-2">
                            <button
                                onClick={() => setExportedMedia(null)}
                                className="flex-1 h-[34px] rounded-xl border border-[rgba(218,220,224,0.15)] hover:bg-white/5 active:bg-white/10 text-[12px] font-medium text-white tracking-[0.1px] transition-all cursor-pointer select-none"
                            >
                                Close
                            </button>
                        </div>
                    </div>
                </div>
            )}
            {isRendering && (
                <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex items-center justify-center cursor-wait">
                    <div className="flex flex-col items-center gap-5">
                        {/* Braille-style dot loader */}
                        <div className="braille-loader" aria-label="Rendering">
                            <span /><span /><span /><span />
                        </div>
                        <span className="text-[14px] font-medium text-white tracking-[0.1px]">
                            Rendering {Math.round(renderProgress * 100)}%
                        </span>
                        <span className="text-[12px] text-white/60 tracking-[0.1px] max-w-[240px] text-center leading-relaxed">
                            This may take a minute.<br />Don&apos;t switch tabs.
                        </span>
                        <button
                            onClick={() => abortControllerRef.current?.abort()}
                            className="mt-2 h-[34px] px-6 rounded-lg border border-white/30 hover:bg-white/10 active:bg-white/20 text-[12px] font-medium text-white/80 tracking-[0.1px] transition-all cursor-pointer select-none"
                        >
