                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useEffect, useRef, useMemo, memo, useState } from 'react';
import { createTimeline, stagger, splitText, steps, spring } from 'animejs';
import { TextConfig, TRANSITION_EFFECTS } from '../types';
import { timeController } from '../services/TimeController';

interface AnimatedTextProps {
    config: TextConfig;
    isPlaying: boolean;
    animationKey: number;
    selectedId: string | null;
    flashLayerId: string | null;
    onSelectLayer: (e: React.MouseEvent, id: string) => void;
}

// Module-level style injection — runs once, not per effect rebuild
const STYLE_ID = 'video-sketch-animation-styles';
if (typeof document !== 'undefined' && !document.getElementById(STYLE_ID)) {
    const styleEl = document.createElement('style');
    styleEl.id = STYLE_ID;
    styleEl.innerHTML = `\n        .line-wrap { display: block; }\n    `;
    document.head.appendChild(styleEl);
}

function getAnimParts(
    h2: HTMLElement,
    granularity: string,
    root: HTMLElement,
    effect: string
): { parts: HTMLElement[] | null; splitter: any } {
    if (granularity === 'line') {
        const lineEls = root.querySelectorAll('.line-wrap');
        return {
            parts: lineEls.length > 0 ? Array.from(lineEls) as HTMLElement[] : null,
            splitter: null
        };
    }

    // Split text into words or chars for per-element animation
    const splitKey = granularity === 'word' ? 'words' : 'chars';

    const splitOpts: any = {};
    if (splitKey === 'words') {
        splitOpts.words = true;
    } else {
        splitOpts.chars = true;
    }

    const splitter = splitText(h2, splitOpts);
    const parts = splitter[splitKey as 'chars' | 'words'];
    return {
        parts: (parts && parts.length > 0) ? Array.from(parts) as HTMLElement[] : null,
        splitter
    };
}

/** Shared stagger timing calculation */
function computeStagger(n: number, inDur: number, granularity: string) {
    const perDur = Math.min(
        granularity === 'line' ? Math.max(200, inDur * 0.5)
            : granularity === 'char' ? Math.max(80, inDur * 0.3)
                : Math.max(150, inDur * 0.4),
        inDur
    );
    const sd = n > 1 ? Math.max(0, (inDur - perDur) / (n - 1)) : 0;
    return { perDur, sd };
}

const AnimatedTextComponent: React.FC<AnimatedTextProps> = ({ config, isPlaying, animationKey, selectedId, flashLayerId, onSelectLayer }) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const timelineRef = useRef<any>(null);
    const splitterRef = useRef<any>(null);
    const configRef = useRef(config);
    configRef.current = config;
    const [flashActive, setFlashActive] = useState(false);

    // Flash glow when this layer is flashed
    useEffect(() => {
        if (flashLayerId === config.id) {
            setFlashActive(true);
            const t = setTimeout(() => setFlashActive(false), 400);
            return () => clearTimeout(t);
        } else {
            setFlashActive(false);
        }
    }, [flashLayerId, config.id]);

    const styles = useMemo(() => ({
        fontFamily: config.fontFamily,
        fontSize: config.fontSize + 'px',
        fontWeight: config.fontWeight,
        letterSpacing: config.letterSpacing + 'px',
        textAlign: config.textAlign as any,
        color: config.color,
        lineHeight: config.lineHeight,
        whiteSpace: 'pre-wrap' as const,
    }), [config.fontFamily, config.fontSize, config.fontWeight, config.letterSpacing, config.textAlign, config.color, config.lineHeight]);

    // Build animation
    useEffect(() => {
        if (!rootRef.current) return;

        // Clean up previous splitter to avoid DOM leaks
        if (splitterRef.current) {
            try { splitterRef.current.revert(); } catch { }
            splitterRef.current = null;
        }

        const content = config.content || '';
        const speedMul = 1 / (config.speed || 1);
        const inEase = config.easing === 'linear' ? 'linear' : spring({ bounce: 0.5, duration: 628 });
        const outEase = config.easing === 'linear' ? 'linear' : spring({ bounce: 0, duration: 400 });
        const granularity = config.granularity || 'word';

        // Reset
        timelineRef.current = null;

        // HTML Generation
        if (granularity === 'line' && config.effect !== 'none') {
            const lines = content.split(String.fromCharCode(10));
            rootRef.current.innerHTML = '<' + 'h2>' + lines.map(l => '<' + 'span class="line-wrap">' + (l || '&nbsp;') + '<' + '/span>').join('') + '<' + '/h2>';
        } else {
            rootRef.current.innerHTML = '<' + 'h2>' + content + '<' + '/h2>';
        }

        const h2 = rootRef.current.querySelector('h2')!;
        const applyStyles = (el: HTMLElement) => {
            el.style.margin = '0'; el.style.padding = '0';
            el.style.fontSize = 'inherit'; el.style.fontWeight = 'inherit';
            el.style.fontFamily = 'inherit'; el.style.color = 'inherit';
            el.style.textAlign = 'inherit'; el.style.letterSpacing = 'inherit';
            el.style.lineHeight = config.lineHeight.toString();
            el.style.whiteSpace = 'pre-wrap';
        };
        applyStyles(h2);

        if (config.effect === 'none') return;

        // Timeline-based effects
        const tl = createTimeline({ autoplay: false });
        const inDur = config.inDuration * speedMul;
        const outDur = config.outDuration * speedMul;
        const inStart = config.delay;
        const outStart = config.delay + config.duration - outDur;

        const { parts, splitter: sp } = getAnimParts(h2, granularity, rootRef.current, config.effect);
        splitterRef.current = sp;

        if (parts && parts.length > 0) {
            const n = parts.length;

            if (config.effect === 'typewriter') {
                const stepDur = 1;
                const staggerInt = n > 1 ? (inDur - stepDur) / (n - 1) : 0;
                tl.add(parts, { opacity: [0, 1], ease: steps(1), duration: stepDur, delay: stagger(staggerInt) }, inStart);
                if (outDur > 0) {
                    const outStagger = n > 1 ? (outDur - stepDur) / (n - 1) : 0;
                    tl.add(parts, { opacity: [1, 0], duration: 1, ease: steps(1), delay: stagger(outStagger) }, outStart);
                }
            } else if (config.effect === 'slide-fade') {
                const { perDur, sd } = computeStagger(n, inDur, granularity);
                tl.add(parts, { opacity: [0, 1], ease: inEase, duration: perDur, delay: stagger(sd) }, inStart);
                if (outDur > 0) {
                    const { perDur: od, sd: osd } = computeStagger(n, outDur, granularity);
                    tl.add(parts, { opacity: [1, 0], duration: od, ease: outEase, delay: stagger(osd) }, outStart);
                }
            }
        }

        timelineRef.current = tl;
        tl.seek(timeController.getTime() * 1000);

        return () => {
            if (timelineRef.current) timelineRef.current.pause();
            if (splitterRef.current) {
                try { splitterRef.current.revert(); } catch { }
                splitterRef.current = null;
            }
        };
    }, [config.content, config.effect, config.granularity, config.easing, config.speed, config.inDuration, config.outDuration, config.delay, config.duration, animationKey]);

    // Time subscription
    useEffect(() => {
        const update = (time: number) => {
            const c = configRef.current;
            const timeMs = time * 1000;
            if (timelineRef.current) timelineRef.current.seek(timeMs);

            if (containerRef.current) {
                const isVisible = timeMs >= c.delay && timeMs <= (c.delay + c.duration);
                containerRef.current.style.opacity = isVisible ? '1' : '0';
                containerRef.current.style.pointerEvents = isVisible ? 'auto' : 'none';
            }
        };
        update(timeController.getTime());
        const unsubscribe = timeController.subscribe(update);
        return unsubscribe;
    }, [config.delay, config.duration]);

    return (
        <div
            ref={containerRef}
            onMouseDown={(e) => onSelectLayer(e, config.id)}
            className={`absolute cursor-move active:cursor-grabbing transition-shadow ${selectedId === config.id ? 'ring-1 ring-white/20 rounded-xl' : ''}`}
            style={{
                left: `${config.position.x}%`,
                top: `${config.position.y}%`,
                transform: `translate(-${config.position.x}%, -${config.position.y}%)`,
                width: 'max-content',
                zIndex: selectedId === config.id ? 20 : 10,
                opacity: 0,
                pointerEvents: 'none',
                overflow: 'visible',
                filter: flashActive ? 'drop-shadow(0 0 12px rgba(255,255,255,0.6))' : 'none',
                transition: flashActive ? 'filter 0.08s cubic-bezier(0.22,0.68,0,1)' : 'filter 0.3s cubic-bezier(0.22,0.68,0,1), box-shadow 0.15s',
            }}
        >
            <div ref={rootRef} style={{ ...styles, padding: '0.35em 0.25em' }} />
        </div>
    );
};

export const AnimatedText = memo(AnimatedTextComponent);

import React, { useEffect, useRef, memo } from 'react';
import { AnimationEffect, TextConfig, TRANSITION_EFFECTS } from '../types';
import { SectionLabel } from './Primitives';

interface EffectPickerProps {
    config: TextConfig;
    onUpdate: (updates: Partial<TextConfig>) => void;
}

const TRANSITION_LIST: { id: AnimationEffect; label: string }[] = [
    { id: 'none', label: 'None' },
    { id: 'slide-fade', label: 'Fade' },
    { id: 'typewriter', label: 'Appear' },
];

/* ─── Mini Preview ─── */
const EffectPreview: React.FC<{
    effect: AnimationEffect; text: string; fontFamily: string; isSelected: boolean; onClick: () => void;
}> = memo(({ effect, text, fontFamily, isSelected, onClick }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const el = containerRef.current;
        if (!el) return;
        const styleId = 'effect-preview-keyframes-v3';
        if (!document.getElementById(styleId)) {
            const style = document.createElement('style');
            style.id = styleId;
            style.textContent = `\n                @keyframes ep-type { 0%{opacity:0} 12%{opacity:1} 75%{opacity:1} 76%{opacity:0} 100%{opacity:0} }\n                @keyframes ep-fade { 0%{opacity:0} 20%{opacity:1} 80%{opacity:1} 100%{opacity:0} }\n            `;
            document.head.appendChild(style);
        }

        let previewWords = text.split(' ').filter(w => w.length > 0).slice(0, 2);
        if (previewWords.length === 0) previewWords = ['Text'];
        // Cap total length to 8 chars
        let total = 0;
        previewWords = previewWords.reduce<string[]>((acc, w) => {
            if (total >= 8) return acc;
            const trimmed = w.slice(0, 8 - total);
            total += trimmed.length;
            acc.push(trimmed);
            return acc;
        }, []);
        const dur = 2500;
        let html = '';

        const wordAnim = (kf: string) =>
            previewWords.map((w, i) => {
                const d = (i / previewWords.length) * (dur * 0.3);
                return `${'<'}span style="display:inline-block;animation:${kf} ${dur}ms ${d}ms ease-out infinite;opacity:0"${'>'} ${w}<${'/'}span>`;
            }).join('&nbsp;');

        if (effect === 'none') html = `${'<'}span${'>'} ${previewWords.join(' ')}<${'/'}span>`;
        else if (effect === 'typewriter') html = wordAnim('ep-type');
        else if (effect === 'slide-fade') html = wordAnim('ep-fade');

        el.innerHTML = html;
    }, [effect, text]);

    return (
        <button onClick={onClick}
            className={`flex flex-col items-center gap-1.5 rounded-lg border transition-all p-1.5\n                ${isSelected ? 'border-white/30 bg-white/[0.08] ring-1 ring-white/10' : 'border-white/[0.06] bg-white/[0.02] hover:border-white/[0.15] hover:bg-white/[0.04]'}`}>
            <div ref={containerRef}
                className="w-full h-[42px] flex items-center justify-center overflow-hidden rounded-md text-[11px] text-white/80"
                style={{ fontFamily, letterSpacing: '-0.3px', fontWeight: 500 }} />
            <span className={`text-[9px] tracking-wide font-medium transition-colors ${isSelected ? 'text-white/70' : 'text-white/25'}`}>
                {TRANSITION_LIST.find(e => e.id === effect)?.label}
            </span>
        </button>
    );
});

/* ─── Main Export ─── */
export const EffectPicker: React.FC<EffectPickerProps> = ({ config, onUpdate }) => {
    const handleEffectClick = (id: AnimationEffect) => {
        const updates: Partial<TextConfig> = {
            effect: id,
            granularity: 'word',
            easing: 'smooth'
        };

        if (id !== 'none' && config.inDuration === 0 && config.outDuration === 0) {
            updates.inDuration = 800;
        }
        onUpdate(updates);
    };

    return (
        <div className="space-y-3 w-full">
            <SectionLabel>Effect</SectionLabel>
            <div className="grid grid-cols-3 gap-1.5 w-full">
                {TRANSITION_LIST.map(eff => (
                    <EffectPreview key={eff.id} effect={eff.id} text={config.content} fontFamily={config.fontFamily}
                        isSelected={config.effect === eff.id} onClick={() => handleEffectClick(eff.id)} />
                ))}
            </div>
        </div>
    );
};

