import React, { useRef, useEffect, useCallback, useState, useMemo } from 'react';
import { SketchConfig, SketchPath, GlobalBrush } from '../types';
import { timeController } from '../services/TimeController';

interface SketchCanvasProps {
    config: SketchConfig;
    isSelected: boolean;
    isPlaying: boolean;
    animationKey: number;
    flashLayerId: string | null;
    globalBrush: GlobalBrush;
    onUpdatePaths: (paths: SketchPath[]) => void;
    onRequestPause: () => void;
}

/** Convert raw points to a smooth SVG path string using Catmull-Rom interpolation */
function smoothPath(points: Array<{ x: number; y: number }>): string {
    if (points.length === 0) return '';
    if (points.length === 1) return `M ${points[0].x} ${points[0].y}`;
    if (points.length === 2) return `M ${points[0].x} ${points[0].y} L ${points[1].x} ${points[1].y}`;

    // Catmull-Rom → cubic Bézier
    let d = `M ${points[0].x} ${points[0].y}`;

    for (let i = 0; i < points.length - 1; i++) {
        const p0 = points[Math.max(0, i - 1)];
        const p1 = points[i];
        const p2 = points[Math.min(points.length - 1, i + 1)];
        const p3 = points[Math.min(points.length - 1, i + 2)];

        const tension = 6; // Higher = less curvy
        const cp1x = p1.x + (p2.x - p0.x) / tension;
        const cp1y = p1.y + (p2.y - p0.y) / tension;
        const cp2x = p2.x - (p3.x - p1.x) / tension;
        const cp2y = p2.y - (p3.y - p1.y) / tension;

        d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.x} ${p2.y}`;
    }

    return d;
}

/** Down-sample consecutive points that are very close together */
function simplifyPoints(points: Array<{ x: number; y: number }>, minDist = 2): Array<{ x: number; y: number }> {
    if (points.length <= 2) return points;
    const result = [points[0]];
    for (let i = 1; i < points.length; i++) {
        const prev = result[result.length - 1];
        const dx = points[i].x - prev.x;
        const dy = points[i].y - prev.y;
        if (dx * dx + dy * dy >= minDist * minDist) {
            result.push(points[i]);
        }
    }
    // Always include last point
    if (result[result.length - 1] !== points[points.length - 1]) {
        result.push(points[points.length - 1]);
    }
    return result;
}

/** Generate an SVG circle cursor data URL */
function buildCircleCursor(size: number, isEraser: boolean): string {
    const r = Math.max(1, size / 2 - 1);
    const stroke = isEraser ? 'rgba(255,100,100,0.8)' : 'rgba(255,255,255,0.8)';
    const svg = `${'<'}svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}"${'>'} ${'<'}circle cx="${size / 2}" cy="${size / 2}" r="${r}" fill="none" stroke="${stroke}" stroke-width="1.5"/${'>'} ` + '<' + '/svg>';
    const encoded = encodeURIComponent(svg);
    const half = Math.round(size / 2);
    return `url("data:image/svg+xml,${encoded}") ${half} ${half}, crosshair`;
}

export const SketchCanvas: React.FC<SketchCanvasProps> = ({
    config,
    isSelected,
    isPlaying,
    animationKey,
    flashLayerId,
    globalBrush,
    onUpdatePaths,
    onRequestPause,
}) => {
    const svgRef = useRef<SVGSVGElement>(null);
    const drawingPoints = useRef<Array<{ x: number; y: number }>>([]);
    const isDrawing = useRef(false);
    const [liveD, setLiveD] = useState<string | null>(null);
    const [isEraserMode, setIsEraserMode] = useState(false);
    const [erasingPathIds, setErasingPathIds] = useState<Set<string>>(new Set());
    const [fadingPathIds, setFadingPathIds] = useState<Set<string>>(new Set());
    const isErasing = useRef(false);
    const [containerOpacity, setContainerOpacity] = useState(0);
    const [elapsed, setElapsed] = useState(0);
    const pathLengths = useRef<Record<string, number>>({});
    const [, setLengthUpdateTick] = useState(0); // To trigger re-render
    const [flashActive, setFlashActive] = useState(false);

    // Flash glow when this layer is flashed
    useEffect(() => {
        if (flashLayerId === config.id) {
            setFlashActive(true);
            const t = setTimeout(() => setFlashActive(false), 400);
            return () => clearTimeout(t);
        } else {
            setFlashActive(false);
        }
    }, [flashLayerId, config.id]);

    // Track Alt key for eraser mode
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Alt') setIsEraserMode(true);
        };
        const handleKeyUp = (e: KeyboardEvent) => {
            if (e.key === 'Alt') setIsEraserMode(false);
        };
        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('keyup', handleKeyUp);
        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            window.removeEventListener('keyup', handleKeyUp);
        };
    }, []);

    // Subscribe to timeController for animation
    useEffect(() => {
        const update = (timeSec: number) => {
            const timeMs = timeSec * 1000;
            const { delay, duration, inDuration, outDuration, effect } = config;
            const endMs = delay + duration;

            if (timeMs < delay || timeMs > endMs) {
                setContainerOpacity(0);
                setElapsed(0);
                return;
            }

            const el = timeMs - delay;
            let opacity = 1;

            // Entrance
            if (effect === 'fade' && el < inDuration && inDuration > 0) {
                opacity = el / inDuration;
            }

            // Exit
            const exitStart = duration - outDuration;
            if (el > exitStart && outDuration > 0) {
                const t = 1 - (el - exitStart) / outDuration;
                if (effect === 'fade') {
                    opacity = Math.min(opacity, t);
                } else if (effect === 'draw-in') {
                    opacity = t;
                }
            }

            setContainerOpacity(Math.max(0, Math.min(1, opacity)));
            setElapsed(el);
        };
        // Run immediately with current time so initial render is correct
        update(timeController.getTime());
        const unsubscribe = timeController.subscribe(update);
        return unsubscribe;
    }, [config.delay, config.duration, config.inDuration, config.outDuration, config.effect]);

    const getSVGPoint = useCallback((e: React.PointerEvent) => {
        const svg = svgRef.current;
        if (!svg) return { x: 0, y: 0 };
        const rect = svg.getBoundingClientRect();
        return {
            x: ((e.clientX - rect.left) / rect.width) * 100,
            y: ((e.clientY - rect.top) / rect.height) * 100,
        };
    }, []);

    const handlePointerDown = useCallback((e: React.PointerEvent) => {
        if (!isSelected) return;

        // Auto-pause if playing — pause and re-dispatch so drawing starts in one click
        if (isPlaying) {
            onRequestPause();
            const { clientX, clientY, pointerId, pointerType } = e.nativeEvent;
            requestAnimationFrame(() => {
                requestAnimationFrame(() => {
                    const el = document.elementFromPoint(clientX, clientY);
                    if (el) {
                        el.dispatchEvent(new PointerEvent('pointerdown', {
                            clientX, clientY, pointerId, pointerType,
                            bubbles: true, cancelable: true, isPrimary: true,
                        }));
                    }
                });
            });
            return;
        }

        // Eraser mode — tldraw-style soft delete
        if (isEraserMode || globalBrush.brushType === 'eraser') {
            e.stopPropagation();
            e.preventDefault();
            const svg = svgRef.current;
            if (svg) svg.setPointerCapture(e.pointerId);

            isErasing.current = true;
            const target = e.target as SVGElement;
            const pathId = target.closest('[data-path-id]')?.getAttribute('data-path-id');
            if (pathId) {
                setErasingPathIds(new Set([pathId]));
            } else {
                setErasingPathIds(new Set());
            }
            return;
        }

        e.stopPropagation();
        e.preventDefault();
        const svg = svgRef.current;
        if (svg) svg.setPointerCapture(e.pointerId);

        isDrawing.current = true;
        const pt = getSVGPoint(e);
        drawingPoints.current = [pt];
        setLiveD(`M ${pt.x} ${pt.y}`);
    }, [isSelected, isPlaying, isEraserMode, globalBrush.brushType, getSVGPoint, onRequestPause]);

    const handlePointerMove = useCallback((e: React.PointerEvent) => {
        // Eraser drag — mark paths under cursor
        if (isErasing.current) {
            const target = e.target as SVGElement;
            const pathId = target.closest('[data-path-id]')?.getAttribute('data-path-id');
            if (pathId) {
                setErasingPathIds(prev => {
                    if (prev.has(pathId)) return prev;
                    const next = new Set(prev);
                    next.add(pathId);
                    return next;
                });
            }
            return;
        }

        if (!isDrawing.current) return;
        const pt = getSVGPoint(e);
        drawingPoints.current.push(pt);
        // Simplify and smooth for live preview
        const simplified = simplifyPoints(drawingPoints.current);
        setLiveD(smoothPath(simplified));
    }, [getSVGPoint]);

    const handlePointerUp = useCallback((e: React.PointerEvent) => {
        const svg = svgRef.current;
        if (svg) svg.releasePointerCapture(e.pointerId);

        // Eraser release — fade out marked paths then remove them
        if (isErasing.current) {
            isErasing.current = false;
            const toRemove = new Set(erasingPathIds);
            if (toRemove.size === 0) return;

            // Start fade-out animation
            setFadingPathIds(toRemove);
            setErasingPathIds(new Set());

            // After fade transition, actually remove the paths
            setTimeout(() => {
                setFadingPathIds(new Set());
                onUpdatePaths(config.paths.filter(p => !toRemove.has(p.id)));
            }, 200);
            return;
        }

        if (!isDrawing.current) return;
        isDrawing.current = false;

        const simplified = simplifyPoints(drawingPoints.current);
        if (simplified.length < 2) {
            setLiveD(null);
            return;
        }

        const d = smoothPath(simplified);
        const newPath: SketchPath = {
            id: Math.random().toString(36).substr(2, 9),
            d,
            stroke: globalBrush.strokeColor,
            strokeWidth: globalBrush.strokeWidth,
            opacity: globalBrush.strokeOpacity,
        };

        onUpdatePaths([...config.paths, newPath]);
        setLiveD(null);
        drawingPoints.current = [];
    }, [globalBrush.strokeColor, globalBrush.strokeWidth, globalBrush.strokeOpacity, config.paths, onUpdatePaths, erasingPathIds]);

    // Measure path lengths in user units for draw-in animation
    useEffect(() => {
        if (config.effect === 'draw-in') {
            const svg = svgRef.current;
            if (svg) {
                const paths = svg.querySelectorAll('path[data-path-id]');
                let changed = false;
                paths.forEach(pathEl => {
                    const pathId = pathEl.getAttribute('data-path-id');
                    if (pathId) {
                        const length = (pathEl as SVGPathElement).getTotalLength();
                        if (pathLengths.current[pathId] !== length) {
                            pathLengths.current[pathId] = length;
                            changed = true;
                        }
                    }
                });
                if (changed) {
                    setLengthUpdateTick(t => t + 1);
                }
            }
        }
    }, [config.paths, config.effect]);


    // Drawing is allowed when selected AND visible at current time.
    // When invisible (opacity 0), pointer events pass through to Stage for smart sketch switching.
    const canDraw = isSelected && containerOpacity > 0;
    const svgScale = svgRef.current ? svgRef.current.getBoundingClientRect().width / 100 : 1;
    const isEraserActive = isEraserMode || globalBrush.brushType === 'eraser';

    // Dynamic circle cursor — strokeWidth is already in CSS pixels (vectorEffect=non-scaling-stroke)
    const cursorStyle = useMemo(() => {
        if (!canDraw) return 'default';
        if (isEraserActive) {
            return buildCircleCursor(16, true);
        }
        // strokeWidth is in CSS pixels thanks to non-scaling-stroke, so use it directly
        const size = Math.max(6, globalBrush.strokeWidth + 2);
        return buildCircleCursor(size, false);
    }, [canDraw, isEraserActive, globalBrush.strokeWidth]);

    return (
        <svg
            ref={svgRef}
            className="absolute inset-0 w-full h-full"
            viewBox="0 0 100 100"
            preserveAspectRatio="none"
            style={{
                pointerEvents: canDraw ? 'auto' : 'none',
                cursor: cursorStyle,
                opacity: containerOpacity,
                zIndex: isSelected ? 15 : 10,
                touchAction: 'none',
                filter: flashActive ? 'drop-shadow(0 0 12px rgba(255,255,255,0.6))' : 'none',
                transition: flashActive ? 'filter 0.08s cubic-bezier(0.22,0.68,0,1)' : 'filter 0.3s cubic-bezier(0.22,0.68,0,1)',
            }}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
        >
            <defs>
                <filter id={`canvas-jitter-1-${config.id}`}>
                    <feTurbulence type="fractalNoise" baseFrequency={config.jitterFrequency || 0.05} numOctaves="2" seed="1" result="noise" />
                    <feDisplacementMap in="SourceGraphic" in2="noise" scale={config.jitterScale || 3} xChannelSelector="R" yChannelSelector="G" />
                </filter>
                <filter id={`canvas-jitter-2-${config.id}`}>
                    <feTurbulence type="fractalNoise" baseFrequency={config.jitterFrequency || 0.05} numOctaves="2" seed="2" result="noise" />
                    <feDisplacementMap in="SourceGraphic" in2="noise" scale={config.jitterScale || 3} xChannelSelector="R" yChannelSelector="G" />
                </filter>
                <filter id={`canvas-jitter-3-${config.id}`}>
                    <feTurbulence type="fractalNoise" baseFrequency={config.jitterFrequency || 0.05} numOctaves="2" seed="3" result="noise" />
                    <feDisplacementMap in="SourceGraphic" in2="noise" scale={config.jitterScale || 3} xChannelSelector="R" yChannelSelector="G" />
                </filter>
            </defs>

            {/* Rendered paths */}
            {config.paths.map((path, index) => {
                const isJitter = config.effect === 'jitter';
                const isDrawIn = config.effect === 'draw-in';

                // For jitter: cycle through 3 filter seeds based on elapsed time
                const jitterFilterId = isJitter
                    ? `canvas-jitter-${(Math.floor((elapsed / 100) % 3) + 1)}-${config.id}`
                    : undefined;

                const userLength = pathLengths.current[path.id] || 0;
                const pixelLength = userLength * svgScale;

                // Calculate sequential draw progress
                let pathDrawProgress = 1;
                if (isDrawIn && config.inDuration > 0) {
                    const totalLength = config.paths.reduce((sum, p) => sum + (pathLengths.current[p.id] || 0), 0);

                    if (totalLength > 0) {
                        const pathDuration = (userLength / totalLength) * config.inDuration;
                        let pathStartTime = 0;
                        for (let i = 0; i < index; i++) {
                            const prevLength = pathLengths.current[config.paths[i].id] || 0;
                            pathStartTime += (prevLength / totalLength) * config.inDuration;
                        }
                        const pathElapsed = elapsed - pathStartTime;
                        if (pathElapsed < 0) pathDrawProgress = 0;
                        else if (pathElapsed > pathDuration) pathDrawProgress = 1;
                        else pathDrawProgress = pathElapsed / pathDuration;
                    }
                }

                return (
                    <path
                        key={path.id}
                        data-path-id={path.id}
                        d={path.d}
                        fill="none"
                        stroke={path.stroke}
                        strokeWidth={path.strokeWidth}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        opacity={
                            fadingPathIds.has(path.id) ? 0 :
                            erasingPathIds.has(path.id) ? path.opacity * 0.3 :
                            path.opacity
                        }
                        vectorEffect="non-scaling-stroke"
                        filter={jitterFilterId ? `url(#${jitterFilterId})` : undefined}
                        style={{
                            strokeDasharray: isDrawIn ? pixelLength : 'none',
                            strokeDashoffset: isDrawIn ? pixelLength * (1 - pathDrawProgress) : 0,
                            transition: fadingPathIds.has(path.id)
                                ? 'opacity 200ms ease-out'
                                : erasingPathIds.has(path.id)
                                    ? 'opacity 80ms ease-out'
                                    : isPlaying ? 'none' : 'stroke-dashoffset 50ms linear',
                        }}
                        className={`\n                            ${isEraserActive && isSelected && !erasingPathIds.has(path.id) ? 'hover:opacity-50 cursor-cell' : ''}\n                        `}
                    />
                );
            })}

            {/* Live drawing preview */}
            {liveD && (
                <path
                    d={liveD}
                    fill="none"
                    stroke={globalBrush.strokeColor}
                    strokeWidth={globalBrush.strokeWidth}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    opacity={globalBrush.strokeOpacity * 0.7}
                    vectorEffect="non-scaling-stroke"
                />
            )}

            {/* Selection border when selected & editable */}
            {isSelected && !isPlaying && (
                <rect
                    x="0" y="0" width="100" height="100"
                    fill="none"
                    stroke="rgba(150,150,150,0.3)"
                    strokeWidth="0.3"
                    strokeDasharray="2 2"
                    vectorEffect="non-scaling-stroke"
                />
            )}
        </svg>
    );
};

import React, { useEffect, useRef, memo } from 'react';
import { SketchEffect, SketchPath } from '../types';
import { SectionLabel } from './Primitives';

interface SketchEffectPickerProps {
    effect: SketchEffect;
    paths: SketchPath[];
    jitterFrequency?: number;
    jitterScale?: number;
    onUpdate: (effect: SketchEffect) => void;
}

const SKETCH_EFFECTS_LIST: { id: SketchEffect; label: string }[] = [
    { id: 'none', label: 'None' },
    { id: 'fade', label: 'Fade' },
    { id: 'draw-in', label: 'Draw In' },
    { id: 'jitter', label: 'Jitter' },
];

const SketchEffectPreview: React.FC<{
    effect: SketchEffect;
    paths: SketchPath[];
    isSelected: boolean;
    jitterFrequency?: number;
    jitterScale?: number;
    onClick: () => void;
}> = memo(({ effect, paths, isSelected, jitterFrequency, jitterScale, onClick }) => {
    useEffect(() => {
        const styleId = 'sketch-effect-preview-keyframes';
        if (!document.getElementById(styleId)) {
            const style = document.createElement('style');
            style.id = styleId;
            style.textContent = `\n                @keyframes sep-fade { 0%{opacity:0} 20%{opacity:1} 80%{opacity:1} 100%{opacity:0} }\n                @keyframes sep-draw {\n                    0% { stroke-dashoffset: 1; }\n                    50% { stroke-dashoffset: 0; }\n                    100% { stroke-dashoffset: 0; }\n                }\n                @keyframes sep-jitter {\n                    0% { filter: url(#sep-jitter-1); }\n                    33% { filter: url(#sep-jitter-2); }\n                    66% { filter: url(#sep-jitter-3); }\n                    100% { filter: url(#sep-jitter-1); }\n                }\n            `;
            document.head.appendChild(style);
        }
    }, []);

    const getStyle = (): React.CSSProperties => {
        if (effect === 'fade') return { animation: 'sep-fade 2s infinite' };
        if (effect === 'jitter') return { animation: 'sep-jitter 0.3s steps(1) infinite' };
        return {};
    };

    const getPathStyle = (path: SketchPath): React.CSSProperties => {
        if (effect === 'draw-in') {
            return {
                strokeDasharray: 1,
                animation: 'sep-draw 2s infinite',
            };
        }
        return {};
    };

    return (
        <button onClick={onClick}
            className={`flex flex-col items-center gap-1.5 rounded-lg border transition-all p-1.5 w-full\n                ${isSelected ? 'border-white/30 bg-white/[0.08] ring-1 ring-white/10' : 'border-white/[0.06] bg-white/[0.02] hover:border-white/[0.15] hover:bg-white/[0.04]'}`}>
            <div className="w-full aspect-video flex items-center justify-center overflow-hidden rounded-md bg-black/20" style={getStyle()}>
                {paths.length > 0 ? (
                    <svg viewBox="0 0 100 100" className="w-full h-full" preserveAspectRatio="none">
                        <defs>
                            <filter id="sep-jitter-1">
                                <feTurbulence type="fractalNoise" baseFrequency={jitterFrequency || 0.05} numOctaves="1" seed="1" result="noise" />
                                <feDisplacementMap in="SourceGraphic" in2="noise" scale={jitterScale || 3} xChannelSelector="R" yChannelSelector="G" />
                            </filter>
                            <filter id="sep-jitter-2">
                                <feTurbulence type="fractalNoise" baseFrequency={jitterFrequency || 0.05} numOctaves="1" seed="2" result="noise" />
                                <feDisplacementMap in="SourceGraphic" in2="noise" scale={jitterScale || 3} xChannelSelector="R" yChannelSelector="G" />
                            </filter>
                            <filter id="sep-jitter-3">
                                <feTurbulence type="fractalNoise" baseFrequency={jitterFrequency || 0.05} numOctaves="1" seed="3" result="noise" />
                                <feDisplacementMap in="SourceGraphic" in2="noise" scale={jitterScale || 3} xChannelSelector="R" yChannelSelector="G" />
                            </filter>
                        </defs>
                        {paths.map(path => (
                            <path
                                key={path.id}
                                d={path.d}
                                fill="none"
                                stroke={path.stroke}
                                strokeWidth={path.strokeWidth * 0.2}
                                opacity={path.opacity}
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                pathLength="1"
                                style={getPathStyle(path)}
                            />
                        ))}
                    </svg>
                ) : (
                    <svg viewBox="0 0 100 100" className="w-full h-full opacity-25" preserveAspectRatio="none">
                        <defs>
                            <filter id="sep-jitter-1">
                                <feTurbulence type="fractalNoise" baseFrequency={jitterFrequency || 0.05} numOctaves="1" seed="1" result="noise" />
                                <feDisplacementMap in="SourceGraphic" in2="noise" scale={jitterScale || 3} xChannelSelector="R" yChannelSelector="G" />
                            </filter>
                            <filter id="sep-jitter-2">
                                <feTurbulence type="fractalNoise" baseFrequency={jitterFrequency || 0.05} numOctaves="1" seed="2" result="noise" />
                                <feDisplacementMap in="SourceGraphic" in2="noise" scale={jitterScale || 3} xChannelSelector="R" yChannelSelector="G" />
                            </filter>
                            <filter id="sep-jitter-3">
                                <feTurbulence type="fractalNoise" baseFrequency={jitterFrequency || 0.05} numOctaves="1" seed="3" result="noise" />
                                <feDisplacementMap in="SourceGraphic" in2="noise" scale={jitterScale || 3} xChannelSelector="R" yChannelSelector="G" />
                            </filter>
                        </defs>
                        <path
                            d="M 15 65 C 20 30, 30 25, 40 50 C 50 75, 55 20, 65 40 C 75 60, 80 35, 88 45"
                            fill="none"
                            stroke="white"
                            strokeWidth="2.5"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            pathLength="1"
                            style={effect === 'draw-in' ? { strokeDasharray: 1, animation: 'sep-draw 2s infinite' } : {}}
                        />
                    </svg>
                )}
            </div>
            <span className={`text-[9px] tracking-wide font-medium transition-colors ${isSelected ? 'text-white/70' : 'text-white/25'}`}>
                {SKETCH_EFFECTS_LIST.find(e => e.id === effect)?.label}
            </span>
        </button>
    );
});

export const SketchEffectPicker: React.FC<SketchEffectPickerProps> = ({ effect, paths, jitterFrequency, jitterScale, onUpdate }) => {
    return (
        <div className="space-y-3 w-full">
            <SectionLabel>Effect</SectionLabel>
            <div className="grid grid-cols-2 gap-1.5 w-full">
                {SKETCH_EFFECTS_LIST.map(eff => (
                    <SketchEffectPreview
                        key={eff.id}
                        effect={eff.id}
                        paths={paths}
                        isSelected={effect === eff.id}
                        jitterFrequency={jitterFrequency}
                        jitterScale={jitterScale}
                        onClick={() => onUpdate(eff.id)}
                    />
                ))}
            </div>
        </div>
    );
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { MediaAsset, TextConfig, SketchConfig, SketchPath, GlobalBrush } from '../types';
import { AnimatedText } from './AnimatedText';
import { SketchCanvas } from './SketchCanvas';
import { timeController } from '../services/TimeController';

interface StageProps {
    media: MediaAsset | null;
    configs: TextConfig[];
    sketchConfigs: SketchConfig[];
    selectedId: string | null;
    isPlaying: boolean;
    animationKey: number;
    flashLayerId: string | null;
    onUpdatePosition: (pos: { x: number; y: number }) => void;
    onUpdateSketchPaths: (id: string, paths: SketchPath[]) => void;
    onMetadataLoaded: (duration: number) => void;
    onSelectLayer: (id: string) => void;
    onPause: () => void;
    onAutoAddSketchLayer: () => void;
    globalBrush: GlobalBrush;
    placeholderDuration?: number;
}

export const Stage: React.FC<StageProps> = ({
    media,
    configs,
    sketchConfigs,
    selectedId,
    isPlaying,
    animationKey,
    flashLayerId,
    onUpdatePosition,
    onUpdateSketchPaths,
    onMetadataLoaded,
    onSelectLayer,
    onPause,
    onAutoAddSketchLayer,
    globalBrush,
    placeholderDuration = 8
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [aspectRatio, setAspectRatio] = useState(1920 / 1080);
    const rafId = useRef<number>();
    const lastTime = useRef<number>(performance.now());
    const seekRafId = useRef<number>();

    const updateLoop = useCallback(() => {
        if (isPlaying) {
            const now = performance.now();
            const delta = (now - lastTime.current) / 1000;
            lastTime.current = now;

            if (videoRef.current) {
                timeController.setTime(videoRef.current.currentTime);
            } else {
                const nextTime = (timeController.getTime() + delta) % placeholderDuration;
                timeController.setTime(nextTime);
            }
            rafId.current = requestAnimationFrame(updateLoop);
        }
    }, [isPlaying, placeholderDuration]);

    useEffect(() => {
        lastTime.current = performance.now();
        if (isPlaying) {
            rafId.current = requestAnimationFrame(updateLoop);
        } else {
            if (rafId.current) cancelAnimationFrame(rafId.current);
        }
        return () => {
            if (rafId.current) cancelAnimationFrame(rafId.current);
        };
    }, [isPlaying, updateLoop]);

    useEffect(() => {
        if (!videoRef.current) return;
        if (isPlaying) videoRef.current.play().catch(() => { });
        else videoRef.current.pause();
    }, [isPlaying]);

    // High-performance scrubbing synchronization
    useEffect(() => {
        const unsubscribe = timeController.subscribe((time) => {
            if (!videoRef.current || isPlaying) return;
            // Abs precision seek for scrubbing
            videoRef.current.currentTime = time;
        });

        return unsubscribe;
    }, [isPlaying]);

    const handleMouseDown = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        e.preventDefault(); // Avoid stealing focus from sidebar text input
        onSelectLayer(id);
        setIsDragging(true);
    };

    // Guard flag to prevent re-entry when we dispatch a synthetic pointer event
    const isSyntheticDispatch = useRef(false);

    // Smart sketch layer switching: when drawing, ensure we have a visible sketch at current time
    const handleStagePointerDown = useCallback((e: React.PointerEvent) => {
        // Skip if this is our own synthetic re-dispatch
        if (isSyntheticDispatch.current) {
            isSyntheticDispatch.current = false;
            return;
        }

        // Don't interfere with text layer drags
        const target = e.target as HTMLElement;
        if (target.closest('.cursor-move')) return;

        const currentTimeMs = timeController.getTime() * 1000;

        const selectedSketch = sketchConfigs.find(s => s.id === selectedId);
        if (selectedSketch) {
            const start = selectedSketch.delay;
            const end = selectedSketch.delay + selectedSketch.duration;
            if (currentTimeMs >= start && currentTimeMs <= end) {
                // Current sketch is visible — let the SketchCanvas handle drawing
                return;
            }
        }

        // Current sketch is NOT visible (or none selected). Find a visible one.
        const visibleSketch = sketchConfigs.find(s => {
            const start = s.delay;
            const end = s.delay + s.duration;
            return currentTimeMs >= start && currentTimeMs <= end;
        });

        if (visibleSketch) {
            onSelectLayer(visibleSketch.id);
        } else {
            onAutoAddSketchLayer();
        }

        // Re-dispatch pointer event after React re-renders so the new canvas starts drawing immediately
        const { clientX, clientY, pointerId, pointerType } = e.nativeEvent;
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                const el = document.elementFromPoint(clientX, clientY);
                if (el) {
                    isSyntheticDispatch.current = true;
                    el.dispatchEvent(new PointerEvent('pointerdown', {
                        clientX, clientY, pointerId, pointerType,
                        bubbles: true, cancelable: true, isPrimary: true,
                    }));
                }
            });
        });
    }, [sketchConfigs, selectedId, onSelectLayer, onAutoAddSketchLayer]);

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (!isDragging || !containerRef.current) return;
            const rect = containerRef.current.getBoundingClientRect();
            const x = ((e.clientX - rect.left) / rect.width) * 100;
            const y = ((e.clientY - rect.top) / rect.height) * 100;
            onUpdatePosition({
                x: Math.max(0, Math.min(100, x)),
                y: Math.max(0, Math.min(100, y))
            });
        };

        const handleMouseUp = () => setIsDragging(false);

        if (isDragging) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging, onUpdatePosition]);


    const handleMediaLoad = (e: React.SyntheticEvent<HTMLVideoElement | HTMLImageElement>) => {
        const target = e.currentTarget;
        let w = 0, h = 0;
        if (target instanceof HTMLVideoElement) {
            w = target.videoWidth;
            h = target.videoHeight;
            onMetadataLoaded(target.duration);
        } else if (target instanceof HTMLImageElement) {
            w = target.naturalWidth;
            h = target.naturalHeight;
            onMetadataLoaded(8); // Keep default 8s for images
        }
        if (w && h) setAspectRatio(w / h);
    };

    const bgOpacity = configs.reduce((max, c) => Math.max(max, c.bgOpacity || 0), 0);

    return (
        <div
            ref={containerRef}
            className="relative shadow-2xl bg-black group overflow-hidden select-none border border-white/5 transition-all duration-500 ease-in-out rounded-xl"
            style={{
                aspectRatio: `${aspectRatio}`,
                ...(aspectRatio > 1
                    ? { width: '100%', maxWidth: '100%', maxHeight: '100%' }
                    : { height: '100%', maxHeight: '100%', maxWidth: '100%' }),
                flexShrink: 1,
                minWidth: 0,
                minHeight: 0
            }}
            onPointerDown={handleStagePointerDown}
        >
            {/* Background Media */}
            {!media ? (
                <div className="w-full h-full bg-gradient-to-br from-zinc-800 to-zinc-950" />
            ) : media.type === 'video' ? (
                <video
                    ref={videoRef}
                    src={media.dataUrl}
                    className="w-full h-full object-contain pointer-events-none opacity-80"
                    muted loop playsInline
                    onLoadedMetadata={handleMediaLoad}
                />
            ) : (
                <img
                    src={media.dataUrl}
                    className="w-full h-full object-contain pointer-events-none opacity-80"
                    onLoad={handleMediaLoad}
                />
            )}

            {/* Overlays for DOM Capture */}
            <div id="stage-overlays" className="absolute inset-0 z-10 pointer-events-none">
                {/* Dim Overlay */}
                <div
                    className="absolute inset-0 bg-black pointer-events-none"
                    style={{ opacity: bgOpacity / 100 }}
                />

                {/* Sketch Layers — rendered first so they appear behind text */}
                {sketchConfigs.map(sketch => (
                    <SketchCanvas
                        key={sketch.id}
                        config={sketch}
                        isSelected={selectedId === sketch.id}
                        isPlaying={isPlaying}
                        animationKey={animationKey}
                        flashLayerId={flashLayerId}
                        globalBrush={globalBrush}
                        onUpdatePaths={(paths) => onUpdateSketchPaths(sketch.id, paths)}
                        onRequestPause={onPause}
                    />
                ))}

                {/* Text Layers — rendered after sketches so they appear on top */}
                {configs.map(config => {
                    // Note: We MUST keep elements mounted so AnimeJS doesn't lose ref topology
                    // Visibility logic is pushed to AnimatedText via opacity handling.
                    return (
                        <AnimatedText
                            key={config.id}
                            config={config}
                            isPlaying={isPlaying}
                            animationKey={animationKey}
                            selectedId={selectedId}
                            flashLayerId={flashLayerId}
                            onSelectLayer={handleMouseDown}
                        />
                    );
                })}
            </div>
        </div>
    );
};

import React, { useRef, useEffect, useCallback, memo } from 'react';
import { timeController } from '../services/TimeController';
import { TextConfig, SketchConfig, LayerConfig, isSketchLayer } from '../types';
import { Icon } from './Icon';

interface TimelineProps {
    duration: number;
    configs: TextConfig[];
    sketchConfigs: SketchConfig[];
    selectedId: string | null;
    isPlaying: boolean;
    onPlayPause: () => void;
    onRestart: () => void;
    onSeek: (time: number) => void;
    onUpdateConfig: (updates: Partial<TextConfig>, id: string) => void;
    onUpdateSketchConfig: (updates: Partial<SketchConfig>, id: string) => void;
    onBatchUpdate: (updates: Array<{ id: string; changes: Partial<TextConfig | SketchConfig> }>) => void;
    onSelectLayer: (id: string) => void;
}


/** Minimum block duration in ms — blocks will not shrink below this */
const MIN_BLOCK_MS = 300;

/* ─── Drag state: entirely in refs for zero re-renders ─── */

interface DragState {
    mode: 'move' | 'resize-start' | 'resize-end';
    activeId: string;
    startX: number;
    startDelay: number;
    startDuration: number;
    currentDelay: number;
    currentDuration: number;
}

export const Timeline: React.FC<TimelineProps> = memo(({
    duration, configs, sketchConfigs, selectedId, isPlaying,
    onPlayPause, onRestart, onSeek, onUpdateConfig, onUpdateSketchConfig, onBatchUpdate, onSelectLayer
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const blockRefs = useRef<Map<string, HTMLDivElement>>(new Map());
    const dragRef = useRef<DragState | null>(null);

    const timeTextRef = useRef<HTMLSpanElement>(null);
    const playheadRef = useRef<HTMLDivElement>(null);

    // Keep latest props in refs for closure-free access
    const durationRef = useRef(duration);
    durationRef.current = duration;
    const configsRef = useRef(configs);
    configsRef.current = configs;
    const onSeekRef = useRef(onSeek);
    onSeekRef.current = onSeek;
    const onSelectLayerRef = useRef(onSelectLayer);
    onSelectLayerRef.current = onSelectLayer;
    const onBatchUpdateRef = useRef(onBatchUpdate);
    onBatchUpdateRef.current = onBatchUpdate;
    const onUpdateSketchConfigRef = useRef(onUpdateSketchConfig);
    onUpdateSketchConfigRef.current = onUpdateSketchConfig;
    const sketchConfigsRef = useRef(sketchConfigs);
    sketchConfigsRef.current = sketchConfigs;

    /* ─── Playhead subscription ─── */
    useEffect(() => {
        const unsubscribe = timeController.subscribe((time) => {
            if (timeTextRef.current) timeTextRef.current.innerText = formatTime(time);
            if (durationRef.current > 0 && playheadRef.current) {
                playheadRef.current.style.left = `${(time / durationRef.current) * 100}%`;
            }
        });
        return unsubscribe;
    }, []);

    const getTimeFromX = useCallback((clientX: number) => {
        if (!containerRef.current || durationRef.current === 0) return 0;
        const rect = containerRef.current.getBoundingClientRect();
        const padding = 4;
        const width = rect.width - padding * 2;
        const x = clientX - rect.left - padding;
        return Math.max(0, Math.min(1, x / width)) * durationRef.current;
    }, []);

    /* ─── Seek (scrub playhead on track background) ─── */
    const handleTrackMouseDown = useCallback((e: React.MouseEvent) => {
        if ((e.target as HTMLElement).closest('[data-block-id]')) return;
        onSeekRef.current(getTimeFromX(e.clientX));
        const onMove = (ev: MouseEvent) => onSeekRef.current(getTimeFromX(ev.clientX));
        const onUp = () => {
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', onUp);
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
    }, [getTimeFromX]);

    /* ─── Block drag: only the dragged block moves during drag ─── */
    const startDrag = useCallback((e: React.MouseEvent, id: string, mode: 'move' | 'resize-start' | 'resize-end') => {
        e.stopPropagation();
        e.preventDefault();
        onSelectLayerRef.current(id);

        const currentConfigs = configsRef.current;
        const currentSketchConfigs = sketchConfigsRef.current;
        const config = currentConfigs.find(c => c.id === id) || currentSketchConfigs.find(s => s.id === id);
        if (!config || !containerRef.current) return;

        // Jump playhead for move clicks
        if (mode === 'move') {
            const visibleTime = (config.delay + config.inDuration + 100) / 1000;
            const endTime = (config.delay + config.duration) / 1000;
            onSeekRef.current(Math.min(visibleTime, endTime, durationRef.current));
        }

        dragRef.current = {
            mode,
            activeId: id,
            startX: e.clientX,
            startDelay: config.delay,
            startDuration: config.duration,
            currentDelay: config.delay,
            currentDuration: config.duration,
        };

        // Dragged block: no transition, elevated z-index, slightly transparent
        const draggedEl = blockRefs.current.get(id);
        if (draggedEl) {
            draggedEl.style.transition = 'none';
            draggedEl.style.zIndex = '25';
            draggedEl.style.opacity = '0.85';
        }

        document.body.style.cursor = mode === 'move' ? 'grabbing' : 'ew-resize';

        const onMove = (ev: MouseEvent) => {
            const drag = dragRef.current;
            if (!drag || !containerRef.current) return;

            const rect = containerRef.current.getBoundingClientRect();
            const deltaX = ev.clientX - drag.startX;
            const deltaTimeMs = (deltaX / rect.width) * durationRef.current * 1000;
            const totalMs = durationRef.current * 1000;
            const dur = durationRef.current;

            let newDelay = drag.startDelay;
            let newDuration = drag.startDuration;

            if (drag.mode === 'move') {
                newDelay = Math.max(0, Math.min(totalMs - drag.startDuration, drag.startDelay + deltaTimeMs));
                newDuration = drag.startDuration;
            } else if (drag.mode === 'resize-start') {
                const rawDelay = drag.startDelay + deltaTimeMs;
                const maxDelay = (drag.startDelay + drag.startDuration) - MIN_BLOCK_MS;
                newDelay = Math.max(0, Math.min(maxDelay, rawDelay));
                newDuration = (drag.startDelay + drag.startDuration) - newDelay;
            } else {
                // resize-end
                const rawEnd = (drag.startDelay + drag.startDuration) + deltaTimeMs;
                newDuration = Math.max(MIN_BLOCK_MS, Math.min(totalMs - drag.startDelay, rawEnd - drag.startDelay));
                newDelay = drag.startDelay;
            }

            // Update ONLY the dragged block's DOM — everything else stays put
            const el = blockRefs.current.get(drag.activeId);
            if (el) {
                el.style.left = `${(newDelay / 1000 / dur) * 100}%`;
                el.style.width = `${(newDuration / 1000 / dur) * 100}%`;
            }

            drag.currentDelay = newDelay;
            drag.currentDuration = newDuration;

            // Keep playhead tracking the block during move so the canvas stays in view
            if (drag.mode === 'move') {
                const config = [...configsRef.current, ...sketchConfigsRef.current].find(c => c.id === drag.activeId);
                const inDur = config?.inDuration ?? 0;
                const visibleTime = (newDelay + inDur + 100) / 1000;
                const endTime = (newDelay + newDuration) / 1000;
                onSeekRef.current(Math.min(visibleTime, endTime, durationRef.current));
            }
        };

        const onUp = () => {
            const drag = dragRef.current;

            if (drag) {
                const dur = durationRef.current;

                // Reset all block styles
                blockRefs.current.forEach((el) => {
                    el.style.transition = 'left 150ms ease-out, width 150ms ease-out, opacity 150ms ease-out';
                    el.style.opacity = '';
                    el.style.zIndex = '';
                });

                // Animate dragged block to final position
                const el = blockRefs.current.get(drag.activeId);
                if (el) {
                    el.style.left = `${(drag.currentDelay / 1000 / dur) * 100}%`;
                    el.style.width = `${(drag.currentDuration / 1000 / dur) * 100}%`;
                }

                // After animation, commit to React state
                setTimeout(() => {
                    blockRefs.current.forEach((el) => {
                        el.style.transition = '';
                    });

                    const updates = [{
                        id: drag.activeId,
                        changes: { delay: drag.currentDelay, duration: drag.currentDuration } as Partial<TextConfig | SketchConfig>,
                    }];
                    onBatchUpdateRef.current(updates);
                }, 160);
            }

            document.body.style.cursor = '';
            dragRef.current = null;

            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', onUp);
        };

        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
    }, []);

    /* ─── Block ref callback ─── */
    const setBlockRef = useCallback((id: string) => (el: HTMLDivElement | null) => {
        if (el) blockRefs.current.set(id, el);
        else blockRefs.current.delete(id);
    }, []);

    if (duration === 0) return null;

    return (
        <div className="w-full space-y-2 select-none flex flex-col">
            {/* Controls */}
            <div className="flex items-center justify-between px-1">
                <div className="flex items-center gap-3">
                    <div className="flex items-center gap-1">
                        <button onClick={onPlayPause}
                            className="w-[34px] h-[34px] flex items-center justify-center rounded-xl hover:bg-white/5 active:bg-white/10 transition-colors text-white">
                            <Icon name={isPlaying ? 'pause' : 'play_arrow'} size={18} filled />
                        </button>
                        <button onClick={onRestart}
                            className="w-[34px] h-[34px] flex items-center justify-center rounded-xl hover:bg-white/5 active:bg-white/10 transition-colors text-white">
                            <Icon name="replay" size={16} />
                        </button>
                    </div>
                    <span ref={timeTextRef} style={{ fontFamily: 'Google Sans Flex' }} className="text-[12px] font-medium tracking-[0.1px] text-[rgba(255,255,255,0.35)] tabular-nums">
                        {formatTime(timeController.getTime())}
                    </span>
                </div>
                <span style={{ fontFamily: 'Google Sans Flex' }} className="text-[12px] font-medium tracking-[0.1px] text-[rgba(255,255,255,0.35)] tabular-nums">
                    {formatTime(duration)}
                </span>
            </div>

            {/* Hit area wrapper — extends above the visible track for easier scrubbing */}
            <div
                ref={containerRef}
                onMouseDown={handleTrackMouseDown}
                className="relative w-full cursor-pointer"
                style={{ paddingTop: '12px', marginTop: '-12px' }}
            >
                {/* Visible track — same height as before */}
                <div className="relative h-[48px] w-full bg-transparent rounded-xl border border-[#595959] p-1">
                <div className="absolute inset-x-1 inset-y-0">
                    {configs.map((config, idx) => {
                        const startPercent = ((config.delay || 0) / 1000 / duration) * 100;
                        const widthPercent = ((config.duration || 0) / 1000 / duration) * 100;
                        const isSelected = selectedId === config.id;
                        const inW = (config.inDuration / config.duration) * 100;
                        const outW = (config.outDuration / config.duration) * 100;

                        return (
                            <div
                                key={config.id}
                                ref={setBlockRef(config.id)}
                                data-block-id={config.id}
                                onMouseDown={(e) => startDrag(e, config.id, 'move')}
                                className={`absolute top-1 bottom-1 rounded-lg z-10 cursor-grab active:cursor-grabbing border overflow-hidden group/clip will-change-[left,width] transition-colors\n                                    ${isSelected
                                        ? 'bg-[#969696] border-[#969696] z-20'
                                        : 'bg-transparent border-[#595959] hover:bg-white/5 hover:border-[#7a7a7a]'
                                    }`}
                                style={{ left: `${startPercent}%`, width: `${widthPercent}%`, opacity: 0.75 }}
                            >
                                {/* In/Out fade zones */}
                                <div className={`absolute left-0 top-0 bottom-0 pointer-events-none rounded-l-md ${isSelected ? 'bg-black/10' : 'bg-white/5'}`} style={{ width: `${inW}%` }} />
                                <div className={`absolute right-0 top-0 bottom-0 pointer-events-none rounded-r-md ${isSelected ? 'bg-black/10' : 'bg-white/5'}`} style={{ width: `${outW}%` }} />

                                {/* Resize handles */}
                                <div onMouseDown={(e) => startDrag(e, config.id, 'resize-start')}
                                    className="absolute left-0 top-0 bottom-0 w-2 cursor-ew-resize hover:bg-white/20 z-30 transition-colors" />
                                <div onMouseDown={(e) => startDrag(e, config.id, 'resize-end')}
                                    className="absolute right-0 top-0 bottom-0 w-2 cursor-ew-resize hover:bg-white/20 z-30 transition-colors" />

                                {/* Label */}
                                <div className="absolute inset-0 flex items-center px-3 pointer-events-none overflow-hidden">
                                    <span style={{ fontFamily: 'Google Sans Flex' }} className={`text-[12px] font-medium tracking-[0.1px] whitespace-nowrap truncate ${isSelected ? 'text-black' : 'text-white'}`}>
                                        {config.content || `Layer ${idx + 1}`}
                                    </span>
                                </div>
                            </div>
                        );
                    })}

                    {/* Sketch Blocks */}
                    {sketchConfigs.map((sketch) => {
                        const startPercent = ((sketch.delay || 0) / 1000 / duration) * 100;
                        const widthPercent = ((sketch.duration || 0) / 1000 / duration) * 100;
                        const isSelected = selectedId === sketch.id;
                        const inW = (sketch.inDuration / sketch.duration) * 100;
                        const outW = (sketch.outDuration / sketch.duration) * 100;
                        const ac = sketch.accentColor || '#5ba3a8';

                        return (
                            <div
                                key={sketch.id}
                                ref={setBlockRef(sketch.id)}
                                data-block-id={sketch.id}
                                onMouseDown={(e) => startDrag(e, sketch.id, 'move')}
                                className={`absolute top-1 bottom-1 rounded-lg z-10 cursor-grab active:cursor-grabbing border overflow-hidden group/clip will-change-[left,width] transition-colors\n                                    ${isSelected ? 'z-20' : 'bg-transparent'}`}
                                style={{
                                    left: `${startPercent}%`,
                                    width: `${widthPercent}%`,
                                    opacity: 0.75,
                                    ...(isSelected
                                        ? { backgroundColor: ac, borderColor: ac }
                                        : { borderColor: `${ac}66`, })
                                }}
                                onMouseEnter={(e) => { if (!isSelected) { (e.currentTarget as HTMLElement).style.backgroundColor = `${ac}1a`; (e.currentTarget as HTMLElement).style.borderColor = ac; } }}
                                onMouseLeave={(e) => { if (!isSelected) { (e.currentTarget as HTMLElement).style.backgroundColor = 'transparent'; (e.currentTarget as HTMLElement).style.borderColor = `${ac}66`; } }}
                            >
                                {/* In/Out fade zones */}
                                <div className={`absolute left-0 top-0 bottom-0 pointer-events-none rounded-l-md ${isSelected ? 'bg-black/10' : ''}`}
                                    style={{ width: `${inW}%`, ...(!isSelected ? { backgroundColor: `${ac}1a` } : {}) }} />
                                <div className={`absolute right-0 top-0 bottom-0 pointer-events-none rounded-r-md ${isSelected ? 'bg-black/10' : ''}`}
                                    style={{ width: `${outW}%`, ...(!isSelected ? { backgroundColor: `${ac}1a` } : {}) }} />

                                {/* Resize handles */}
                                <div onMouseDown={(e) => startDrag(e, sketch.id, 'resize-start')}
                                    className="absolute left-0 top-0 bottom-0 w-2 cursor-ew-resize hover:bg-white/20 z-30 transition-colors" />
                                <div onMouseDown={(e) => startDrag(e, sketch.id, 'resize-end')}
                                    className="absolute right-0 top-0 bottom-0 w-2 cursor-ew-resize hover:bg-white/20 z-30 transition-colors" />

                                {/* Label */}
                                <div className="absolute inset-0 flex items-center px-3 pointer-events-none overflow-hidden gap-1.5">
                                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke={isSelected ? 'black' : ac} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                        <path d="M12 19l7-7 3 3-7 7-3-3z" />
                                        <path d="M18 13l-1.5-7.5L2 2l3.5 14.5L13 18l5-5z" />
                                        <path d="M2 2l7.586 7.586" />
                                        <circle cx="11" cy="11" r="2" />
                                    </svg>
                                    <span style={{ fontFamily: 'Google Sans Flex', color: isSelected ? 'black' : ac }} className="text-[12px] font-medium tracking-[0.1px] whitespace-nowrap truncate">
                                        {sketch.name || 'Sketch'}
                                    </span>
                                </div>
                            </div>
                        );
                    })}

                    {/* Playhead */}
                    <div
                        ref={playheadRef}
                        className="absolute top-0 bottom-0 w-px bg-white/80 z-40 pointer-events-none"
                        style={{ left: `${(timeController.getTime() / duration) * 100}%` }}
                    >
                        <div className="absolute -top-1 left-1/2 -translate-x-1/2 w-3.5 h-3.5 bg-white rounded-full shadow-[0_0_8px_rgba(255,255,255,0.4)]" />
                    </div>
                </div>
                </div>
            </div>
        </div>
    );
});

function formatTime(seconds: number) {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const ms = Math.floor((seconds % 1) * 100);
    return `${mins}:${secs.toString().padStart(2, '0')}.${ms.toString().padStart(2, '0')}`;
}

import { Input, Output, Conversion, Mp4OutputFormat, BufferTarget, BlobSource, ALL_FORMATS } from "mediabunny";
import { Flow } from "flow-sdk";
import { toCanvas } from "html-to-image";
import { timeController } from "./TimeController";
import { MediaAsset, TextConfig, SketchConfig } from "../types";

/**
 * Convert ArrayBuffer to base64 in chunks to avoid stack overflow and
 * string size limits that cause corrupt payloads for large videos.
 */
function arrayBufferToBase64(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  const chunkSize = 32768;
  const parts: string[] = [];
  for (let i = 0; i < bytes.length; i += chunkSize) {
    const chunk = bytes.subarray(i, Math.min(i + chunkSize, bytes.length));
    parts.push(String.fromCharCode.apply(null, chunk as unknown as number[]));
  }
  return btoa(parts.join(''));
}

/**
 * Wait for the browser to fully flush DOM updates.
 * Double-rAF ensures React has committed and the compositor has painted.
 */
function doubleRAF(): Promise<void> {
  return new Promise(resolve =>
    requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
  );
}

/** Single rAF — used in render loop where speed matters more. */
function singleRAF(): Promise<void> {
  return new Promise(resolve => requestAnimationFrame(resolve));
}

/**
 * Style properties whitelist for html-to-image.
 * Only these CSS properties are cloned per node, avoiding ~300+ default copies.
 */
const STYLE_WHITELIST = [
  'font-family', 'font-size', 'font-weight', 'font-style',
  'letter-spacing', 'line-height', 'text-align', 'white-space',
  'color', 'text-decoration', 'text-transform',
  'display', 'position', 'top', 'left', 'right', 'bottom',
  'width', 'height', 'min-width', 'min-height', 'max-width', 'max-height',
  'margin', 'padding', 'box-sizing', 'overflow',
  'opacity', 'visibility', 'background', 'background-color',
  'border', 'border-radius', 'box-shadow',
  'transform', 'transform-origin',
  'flex', 'flex-direction', 'align-items', 'justify-content', 'gap',
  'z-index', 'pointer-events',
];

/** Filter out display:none nodes to speed up html-to-image cloning.
 *  Note: we intentionally keep opacity:0 nodes because they still occupy
 *  layout space — removing them shifts text alignment (e.g. right-aligned). */
function visibleFilter(node: HTMLElement): boolean {
  if (node.nodeType !== 1) return true;
  const s = node.style;
  if (s && s.display === 'none') return false;
  return true;
}

/**
 * Get the stage overlay element used for DOM capture.
 */
function getOverlayElement(): HTMLElement | null {
  return document.getElementById("stage-overlays");
}

/**
 * Check if any layer has animated content (effect !== 'none').
 */
function hasAnimatedContent(configs: TextConfig[], sketchConfigs: SketchConfig[]): boolean {
  return configs.some(c => c.effect !== 'none') || sketchConfigs.some(s => s.effect !== 'none');
}

/**
 * Rasterize all sketch SVGs directly via the browser's native SVG renderer.
 * This bypasses html-to-image (which cannot handle SVG filter url() references)
 * by using XMLSerializer → Blob → Image → drawImage().
 *
 * For jitter effects, a random seed (1–3) is selected per-frame to simulate
 * the CSS animation that cycles through displacement filters.
 */
async function rasterizeSketchSVGs(
  overlayEl: HTMLElement,
  outputWidth: number,
  outputHeight: number,
  sketchConfigs: SketchConfig[],
  currentTimeSec: number
): Promise<HTMLCanvasElement | null> {
  // Find all sketch SVG elements inside the overlay
  const sketchSVGs = Array.from(overlayEl.querySelectorAll('svg')) as SVGSVGElement[];
  if (sketchSVGs.length === 0) return null;

  const canvas = document.createElement('canvas');
  canvas.width = outputWidth;
  canvas.height = outputHeight;
  const ctx = canvas.getContext('2d')!;

  const overlayRect = overlayEl.getBoundingClientRect();

  for (const svgEl of sketchSVGs) {
    // Check if this SVG has any sketch paths (skip non-sketch SVGs)
    const hasSketchPaths = svgEl.querySelector('path[data-path-id]');
    if (!hasSketchPaths) continue;

    // Check visibility — if the SVG's opacity is 0, skip it
    const computedOpacity = parseFloat(svgEl.style.opacity || '1');
    if (computedOpacity <= 0) continue;

    // Clone the SVG for serialization
    const clone = svgEl.cloneNode(true) as SVGSVGElement;
    clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');

    // Get the SVG's actual rendered size relative to the overlay
    const svgRect = svgEl.getBoundingClientRect();

    // Set explicit width/height on clone for proper rasterization
    clone.setAttribute('width', String(svgRect.width));
    clone.setAttribute('height', String(svgRect.height));

    // For jitter animation: the filter is already applied inline as a `filter` attribute
    // by SketchCanvas. The filter IDs are scoped per-sketch (canvas-jitter-N-sketchId).
    // For serialization, we just need to ensure the filters are present in the clone.
    // No class-based cleanup needed since jitter is now inline.

    // Remove any style-based animations that won't serialize
    const allPaths = clone.querySelectorAll('path');
    allPaths.forEach(p => {
      // Clear any animation/transition CSS that won't work in static render
      if (p.style.animation) p.style.animation = '';
      if (p.style.transition) p.style.transition = '';
    });

    // Also remove the selection border rect if present
    const selectionRects = clone.querySelectorAll('rect');
    selectionRects.forEach(r => {
      if (r.getAttribute('stroke') === 'rgba(150,150,150,0.3)') {
        r.remove();
      }
    });

    // Serialize and create a blob URL
    const svgString = new XMLSerializer().serializeToString(clone);
    const blob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(blob);

    try {
      const img = new Image();
      await new Promise<void>((resolve, reject) => {
        img.onload = () => resolve();
        img.onerror = (e) => reject(e);
        img.src = url;
      });

      // Compute position and size relative to the overlay, scaled to output
      const scaleX = outputWidth / overlayRect.width;
      const scaleY = outputHeight / overlayRect.height;
      const dx = (svgRect.left - overlayRect.left) * scaleX;
      const dy = (svgRect.top - overlayRect.top) * scaleY;
      const dw = svgRect.width * scaleX;
      const dh = svgRect.height * scaleY;

      ctx.globalAlpha = computedOpacity;
      ctx.drawImage(img, dx, dy, dw, dh);
      ctx.globalAlpha = 1;
    } catch (err) {
      console.warn('Failed to rasterize sketch SVG:', err);
    } finally {
      URL.revokeObjectURL(url);
    }
  }

  return canvas;
}

/**
 * Hide all sketch SVG elements so html-to-image doesn't try to render them
 * (it would lose the SVG filter effects). Returns a restore function.
 */
function hideSketchSVGs(overlayEl: HTMLElement): () => void {
  const sketchSVGs = Array.from(overlayEl.querySelectorAll('svg')) as SVGSVGElement[];
  const originals: { el: SVGSVGElement; display: string }[] = [];

  for (const svgEl of sketchSVGs) {
    const hasSketchPaths = svgEl.querySelector('path[data-path-id]');
    if (!hasSketchPaths) continue;
    originals.push({ el: svgEl, display: svgEl.style.display });
    svgEl.style.display = 'none';
  }

  return () => {
    for (const { el, display } of originals) {
      el.style.display = display;
    }
  };
}



/**
 * Manually fetch Google Fonts CSS and inline the font files as base64.
 * This bypasses the CORS cssRules issue entirely by fetching the raw CSS
 * ourselves and converting woff2 URLs to data URIs.
 */
async function fetchGoogleFontCSS(): Promise<string> {
  const links = Array.from(document.querySelectorAll('link[rel="stylesheet"]'))
    .filter(el => (el as HTMLLinkElement).href?.includes('fonts.googleapis.com'));

  if (links.length === 0) return '';

  const cssChunks: string[] = [];

  for (const link of links) {
    try {
      const res = await fetch((link as HTMLLinkElement).href, {
        headers: { 'Accept': 'text/css' }
      });
      const css = await res.text();

      const urlRegex = new RegExp('url\\((https?:\\/\\/[^)]+)\\)', 'g');
      let inlined = css;
      const matches = [...css.matchAll(urlRegex)];

      for (const match of matches) {
        try {
          const fontRes = await fetch(match[1]);
          const fontBuf = await fontRes.arrayBuffer();
          const b64 = arrayBufferToBase64(fontBuf);
          const mime = match[1].includes('.woff2') ? 'font/woff2'
            : match[1].includes('.woff') ? 'font/woff'
              : 'font/truetype';
          inlined = inlined.replace(match[0], 'url(data:' + mime + ';base64,' + b64 + ')');
        } catch {
          // ignore
        }
      }
      cssChunks.push(inlined);
    } catch {
      // ignore
    }
  }

  return cssChunks.join(String.fromCharCode(10));
}

/**
 * Capture the stage overlays DOM as a canvas image.
 * pixelRatio controls render quality — higher = crisper text at large resolutions.
 */
async function captureOverlay(
  overlayEl: HTMLElement,
  fontCSS: string,
  pixelRatio: number
): Promise<HTMLCanvasElement> {
  return toCanvas(overlayEl, {
    fontEmbedCSS: fontCSS || undefined,
    width: overlayEl.offsetWidth,
    height: overlayEl.offsetHeight,
    pixelRatio,
    skipAutoScale: true,
    includeStyleProperties: STYLE_WHITELIST,
    preferredFontFormat: 'woff2',
    filter: visibleFilter,
  });
}

/**
 * Generate a silent WebM video from a still image canvas at the given FPS and duration.
 * Uses captureStream(0) + requestFrame() to force frame emission on a static canvas.
 * The canvas must be continuously redrawn to ensure captureStream actually produces frames,
 * because browsers skip frame generation when canvas content hasn't changed.
 */
async function generateStillVideo(
  bgCanvas: HTMLCanvasElement,
  durationSec: number,
  fps: number = 24
): Promise<Blob> {
  const ctx = bgCanvas.getContext('2d')!;
  // Snapshot the canvas content so we can redraw it to force frame emission
  const imageData = ctx.getImageData(0, 0, bgCanvas.width, bgCanvas.height);

  const stream = bgCanvas.captureStream(0); // 0 = manual frame control
  const videoTrack = stream.getVideoTracks()[0] as any;

  const mediaRecorder = new MediaRecorder(stream, {
    mimeType: 'video/webm;codecs=vp9',
    videoBitsPerSecond: 8_000_000,
  });

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  return new Promise((resolve, reject) => {
    let redrawInterval: ReturnType<typeof setInterval>;

    mediaRecorder.onstop = () => {
      clearInterval(redrawInterval);
      const blob = new Blob(chunks, { type: 'video/webm' });
      resolve(blob);
    };
    mediaRecorder.onerror = reject;
    mediaRecorder.start();

    // Continuously redraw the canvas + request frames at the target FPS.
    // This runs in real-time so the MediaRecorder timestamps are correct.
    redrawInterval = setInterval(() => {
      ctx.putImageData(imageData, 0, 0);
      if (videoTrack.requestFrame) videoTrack.requestFrame();
    }, 1000 / fps);

    setTimeout(() => {
      mediaRecorder.stop();
      stream.getTracks().forEach(t => t.stop());
    }, durationSec * 1000);
  });
}

// ─── VIDEO EXPORT ───────────────────────────────────────────

export async function renderVideo(
  media: MediaAsset | null,
  configs: TextConfig[],
  onProgress: (p: number) => void,
  signal?: AbortSignal,
  sketchConfigs: SketchConfig[] = [],
  totalDuration: number = 8
) {
  // Smart export: only export as image if the source is an image AND no animated content
  if (media && media.type === "image" && !hasAnimatedContent(configs, sketchConfigs)) {
    return await renderImageOverlay(media, configs, sketchConfigs);
  }

  // Ensure all Google Fonts are loaded before capture
  await document.fonts.ready;

  const overlayEl = getOverlayElement();
  if (!overlayEl) throw new Error("Stage overlay element not found");

  // Pre-compute font embed CSS — manual fetch bypasses CORS cssRules error
  const fontCSS = await fetchGoogleFontCSS();

  let sourceBlob: Blob;
  let outputWidth = 1920;
  let outputHeight = 1080;
  let isPortrait = false;

  if (media && media.type === 'video') {
    // Video background — use the source video directly
    const response = await fetch(media.dataUrl);
    sourceBlob = await response.blob();

    // Detect source dimensions
    const sourceVideo = document.querySelector('video[src]') as HTMLVideoElement | null;
    const srcW = sourceVideo?.videoWidth || 1280;
    const srcH = sourceVideo?.videoHeight || 720;
    isPortrait = srcH > srcW;
    outputWidth = srcW;
    outputHeight = srcH;
  } else {
    // Image background or no background — generate a still video at 24fps
    const bgCanvas = document.createElement('canvas');

    if (media && media.type === 'image') {
      // Draw the image as a still background
      const img = new Image();
      img.src = media.dataUrl;
      await img.decode();
      bgCanvas.width = img.width;
      bgCanvas.height = img.height;
      outputWidth = img.width;
      outputHeight = img.height;
      isPortrait = img.height > img.width;
      const ctx = bgCanvas.getContext('2d')!;
      ctx.drawImage(img, 0, 0);
    } else {
      // No background — use a gradient matching the placeholder
      bgCanvas.width = 1920;
      bgCanvas.height = 1080;
      const ctx = bgCanvas.getContext('2d')!;
      const gradient = ctx.createLinearGradient(0, 0, bgCanvas.width, bgCanvas.height);
      gradient.addColorStop(0, '#27272a'); // zinc-800
      gradient.addColorStop(1, '#09090b'); // zinc-950
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, bgCanvas.width, bgCanvas.height);
    }

    onProgress(0.02);
    // Generate at 1fps to minimize real-time frame callbacks (8 frames vs 192 at 24fps)
    sourceBlob = await generateStillVideo(bgCanvas, totalDuration, 1);
    onProgress(0.05);
  }

  const input = new Input({ source: new BlobSource(sourceBlob), formats: ALL_FORMATS });
  const output = new Output({
    format: new Mp4OutputFormat({ fastStart: "in-memory" }),
    target: new BufferTarget()
  });

  // Lock TimeController so Stage playback loop can't interfere
  timeController.isLocked = true;

  let renderCanvas: HTMLCanvasElement | null = null;
  let renderCtx: CanvasRenderingContext2D | null = null;
  let overlayPixelRatio = 1;

  try {
    const conversion = await Conversion.init({
      input,
      output,
      video: {
        forceTranscode: true,
        frameRate: 24,
        // Set the longer edge to 1080 for crisp output regardless of orientation
        ...(isPortrait ? { width: 1080 } : { height: 1080 }),
        fit: 'contain',
        bitrate: 8_000_000,
        process: async (sample: any) => {
          if (signal?.aborted) {
            throw new Error("Render cancelled");
          }
          const w = sample.displayWidth;
          const h = sample.displayHeight;

          if (!renderCanvas) {
            renderCanvas = document.createElement('canvas');
            renderCanvas.width = w;
            renderCanvas.height = h;
            renderCtx = renderCanvas.getContext('2d')!;

            // Cap pixel ratio at 2 for video export — compressed video doesn't benefit from 3x+
            const previewH = overlayEl.offsetHeight || 540;
            overlayPixelRatio = Math.min(2, Math.max(1, Math.ceil(h / previewH)));
          }

          // 1. Draw the source video frame (mediabunny upscales for us)
          sample.draw(renderCtx!, 0, 0);

          // 2. Seek our animation system to this frame's time
          timeController.forceSetTime(sample.timestamp);

          // 3. Wait for DOM to flush (React + anime.js transforms)
          await singleRAF();

          // 4. Capture the DOM overlay at high resolution
          try {
            // Hide sketch SVGs from html-to-image (it can't handle SVG filters)
            const restoreSketches = hideSketchSVGs(overlayEl);

            // Capture text overlays via html-to-image
            const overlayCanvas = await captureOverlay(overlayEl, fontCSS, overlayPixelRatio);

            // Restore sketch visibility
            restoreSketches();

            // 5. Composite text overlay onto video frame
            renderCtx!.drawImage(overlayCanvas, 0, 0, w, h);

            // 6. Rasterize sketch SVGs separately via native browser SVG pipeline
            //    This preserves feTurbulence/feDisplacementMap filter effects
            const sketchCanvas = await rasterizeSketchSVGs(
              overlayEl, w, h, sketchConfigs, sample.timestamp
            );
            if (sketchCanvas) {
              renderCtx!.drawImage(sketchCanvas, 0, 0, w, h);
            }
          } catch (captureErr) {
            // If capture fails for a single frame, skip overlay (don't crash the export)
            console.warn('Overlay capture failed for frame at', sample.timestamp, captureErr);
          }

          return renderCanvas;
        }
      }
    });

    if (!conversion.isValid) throw new Error("Invalid conversion");
    conversion.onProgress = onProgress;
    await conversion.execute();

    // Create result as blob URL
    const buffer = output.target.buffer;
    const videoBlob = new Blob([buffer], { type: "video/mp4" });
    const dataUrl = URL.createObjectURL(videoBlob);
    const mimeType = "video/mp4";

    // Save via Flow SDK (needs base64 for the API)
    const base64 = arrayBufferToBase64(buffer);
    const flowResult = await Flow.save({
      base64,
      mimeType,
      name: `video-sketch_${Date.now()}.mp4`
    });

    return { flowResult, dataUrl, mimeType };
  } catch (err) {
    throw err;
  } finally {
    // Always unlock TimeController
    timeController.isLocked = false;
  }
}

// ─── IMAGE EXPORT ───────────────────────────────────────────

export async function renderImageOverlay(media: MediaAsset, configs?: TextConfig[], sketchConfigs: SketchConfig[] = []) {
  await document.fonts.ready;

  const overlayEl = getOverlayElement();

  const img = new Image();
  img.src = media.dataUrl;
  await img.decode();

  const canvas = document.createElement("canvas");
  canvas.width = img.width;
  canvas.height = img.height;
  const ctx = canvas.getContext("2d")!;

  // Draw base image
  ctx.drawImage(img, 0, 0);

  // Composite overlays at time 0
  if (overlayEl && ((configs && configs.length > 0) || sketchConfigs.length > 0)) {
    const fontCSS = await fetchGoogleFontCSS();
    const previewH = overlayEl.offsetHeight || 540;
    const pixelRatio = Math.max(1, Math.ceil(img.height / previewH));

    // Seek to time 0 and capture
    timeController.isLocked = true;
    timeController.forceSetTime(0);
    await doubleRAF();

    try {
      // Hide sketches from html-to-image
      const restoreSketches = hideSketchSVGs(overlayEl);
      const overlayCanvas = await captureOverlay(overlayEl, fontCSS, pixelRatio);
      restoreSketches();
      ctx.drawImage(overlayCanvas, 0, 0, img.width, img.height);

      // Rasterize sketch SVGs separately
      const sketchCanvas = await rasterizeSketchSVGs(overlayEl, img.width, img.height, sketchConfigs, 0);
      if (sketchCanvas) {
        ctx.drawImage(sketchCanvas, 0, 0, img.width, img.height);
      }
    } catch (captureErr) {
      console.warn('Overlay capture failed for image export', captureErr);
    } finally {
      timeController.isLocked = false;
    }
  }

  const dataUrl = canvas.toDataURL("image/png");
  const mimeType = "image/png";

  // Auto-save via Flow SDK
  let flowResult;
  try {
    const base64 = dataUrl.split(',')[1];
    flowResult = await Flow.save({ base64, mimeType, name: `video-sketch_${Date.now()}.png` });
  } catch { }

  return { flowResult, dataUrl, mimeType };
}

type Listener = (time: number) => void;

class TimeController {
    private time: number = 1.0;
    private listeners: Set<Listener> = new Set();
    public isLocked: boolean = false;

    setTime(t: number) {
        if (this.isLocked) return;
        this.time = t;
        this.notify();
    }

    forceSetTime(t: number) {
        this.time = t;
        this.notify();
    }

    getTime() {
        return this.time;
    }

    subscribe(listener: Listener) {
        this.listeners.add(listener);
        return () => {
            this.listeners.delete(listener);
        };
    }

    private notify() {
        this.listeners.forEach(l => l(this.time));
    }
}

export const timeController = new TimeController();

export interface MediaAsset {
    type: 'video' | 'image';
    dataUrl: string;
    mimeType?: string;
}

export type AnimationEffect =
    | 'none'
    | 'typewriter'
    | 'slide-fade';

export type AnimationGranularity = 'char' | 'word' | 'line';
export type AnimationEasing = 'linear' | 'smooth';
export type StackTransition = 'blur' | 'cut' | 'fade';

export const TRANSITION_EFFECTS = new Set<AnimationEffect>(['typewriter', 'slide-fade']);

export type SketchEffect = 'none' | 'draw-in' | 'fade' | 'jitter';
export type BrushType = 'brush' | 'eraser';

export interface GlobalBrush {
    strokeColor: string;
    strokeWidth: number;
    strokeOpacity: number;
    brushType: BrushType;
}

export interface SketchPath {
    id: string;
    d: string;          // SVG path data string
    stroke: string;
    strokeWidth: number;
    opacity: number;
}

export interface TextConfig {
    type?: 'text';       // discriminator (optional for back-compat)
    id: string;
    content: string;
    fontFamily: string;
    fontSize: number;
    fontWeight: number;
    letterSpacing: number;
    lineHeight: number;
    textAlign: 'left' | 'center' | 'right';
    color: string;
    backgroundColor: string;
    bgOpacity: number;
    position: { x: number; y: number };
    effect: AnimationEffect;
    granularity: AnimationGranularity;
    easing: AnimationEasing;
    speed: number; // 0.25 – 4, multiplier on animation speed (1 = default)
    stackTransition: StackTransition; // Transition style (reserved for future use)
    duration: number; // Total Lifespan on timeline (ms)
    delay: number;    // Start Time on timeline (ms)
    inDuration: number;  // Entrance Animation length (ms)
    outDuration: number; // Exit Animation length (ms)
    intensity: number;   // 0-200, effect intensity
}

export interface SketchConfig {
    type: 'sketch';
    id: string;
    name: string;
    paths: SketchPath[];
    strokeColor: string;
    strokeWidth: number;
    strokeOpacity: number;
    effect: SketchEffect;
    brushType: BrushType;
    accentColor: string;    // UI accent color for sidebar/timeline
    duration: number;   // Total Lifespan on timeline (ms)
    delay: number;      // Start Time on timeline (ms)
    inDuration: number; // Entrance Animation length (ms)
    outDuration: number;// Exit Animation length (ms)
    jitterFrequency?: number;
    jitterScale?: number;
}

/** Uniform accent color for all sketch layers in the UI */
export const SKETCH_ACCENT_COLOR = '#5ba3a8';

export type LayerConfig = TextConfig | SketchConfig;

export function isSketchLayer(layer: LayerConfig): layer is SketchConfig {
    return layer.type === 'sketch';
}

export function isTextLayer(layer: LayerConfig): layer is TextConfig {
    return layer.type !== 'sketch';
}

